"""Optique CPGE : cours originaux, conventions et problèmes intégralement corrigés."""

from html import escape


def P(label, text):
    return "<p><b>" + escape(label) + "</b> " + escape(text) + "</p>"


def F(text):
    return "<div class='formula'>" + escape(text).replace("\n", "<br>") + "</div>"


def lesson(title, level, lab, *blocks):
    return dict(title=title, level=level, lab=lab, html="".join(blocks))


def exercise(title, level, lab, question, answer):
    return dict(title=title, level=level, lab=lab, question=P("Énoncé.", question), answer=P("Corrigé.", answer))


LESSONS = [
    lesson("1. Du front d’onde au rayon réfracté", "Sup", "snell",
        P("Cadre.", "Un rayon est la trajectoire géométrique associée à une propagation locale. Cette limite demande une longueur d’onde petite devant les échelles de variation du milieu et des obstacles. Dans un milieu isotrope transparent d’indice n, la vitesse de phase est c/n ; λ₀ désigne ici la longueur d’onde dans le vide, λ=λ₀/n celle du milieu."),
        F("n₁ sin i=n₂ sin r ; angle réfléchi=i\nλ₂=λ₀/n₂ ; ν₂=ν₁ ; n₁>n₂ ⇒ ic=arcsin(n₂/n₁)"),
        P("Construction.", "Mesurer les angles depuis la normale, et non depuis la surface. L’invariance de la phase le long de l’interface conserve la composante tangentielle du vecteur d’onde : k₁ sin i=k₂ sin r. La fréquence demeure la même à une interface immobile. Cette démonstration relie géométrie et électromagnétisme."),
        P("Exemple.", "Depuis l’air vers le verre n₂=1,50 à i=45°, r=arcsin(sin45°/1,50)≈28,13°. Dans le sens verre→air, l’angle critique vaut 41,81°. Au-delà il n’existe pas de rayon réfracté propagatif dans l’air, mais un champ évanescent subsiste."),
        P("Technique.", "Avant d’appliquer arcsin, vérifier que son argument est compris entre −1 et 1. Tester n₁=n₂, i=0 et la réversibilité donne trois contrôles qui détectent une erreur d’angle ou d’indice.")),
    lesson("2. Fresnel : un rayon ne transporte pas toujours toute la puissance", "Spé ; prolongement selon filière", "snell",
        P("Objets.", "À une interface diélectrique non magnétique, le champ électrique s est perpendiculaire au plan d’incidence ; p lui appartient. Les amplitudes de champ et les puissances ont des coefficients différents. Les indices réels positifs et les angles sous le seuil critique définissent ici des milieux sans absorption."),
        F("rs=(n₁ cos i−n₂ cos r)/(n₁ cos i+n₂ cos r)\nrp=(n₂ cos i−n₁ cos r)/(n₂ cos i+n₁ cos r)\nR=|r|² ; T=(n₂ cos r)/(n₁ cos i)|t|² ; R+T=1"),
        P("Dérivation.", "La continuité des champs tangentiels E et H fournit deux équations linéaires. Pour convertir une amplitude transmise en puissance, intégrer le flux normal de Poynting : le facteur n cos(angle) est indispensable. Une convention de base p peut inverser le signe de rp sans changer R."),
        P("Brewster.", "Pour p, rp=0 lorsque tan iB=n₂/n₁. Avec n₂/n₁=1,50, iB≈56,31°. Le rayon réfléchi s demeure présent. À incidence normale R=[(n₁−n₂)/(n₁+n₂)]²=4 % pour air/verre ; une plaque à deux faces perd davantage si leurs réflexions sont traitées séparément."),
        P("Lien au TP.", "Comparer s et p au goniomètre permet d’identifier une polarisation et de séparer déviation, réflexion et transmission. Le modèle de rayon seul ne décrit ni l’onde évanescente ni les décalages latéraux au voisinage d’une réflexion totale.")),
    lesson("3. Lentille mince : annoncer les distances orientées", "Sup", "lentille",
        P("Convention.", "L’axe x est orienté dans le sens de propagation, O est le centre de la lentille, p=OA et p′=OA′ sont algébriques. Un objet réel à gauche donne p<0. Une lentille convergente dans l’air a f′>0 et une divergente f′<0. Un trait pointillé représente un prolongement, pas un rayon transportant de l’énergie."),
        F("1/p′−1/p=1/f′ ; p′=f′p/(p+f′)\nγ=A′B′/AB=p′/p ; C=1/f′ en m⁻¹"),
        P("Construction.", "Un rayon passant par O garde sa direction dans le modèle mince ; un rayon parallèle à l’axe sort par F′ ou semble provenir de F′ ; un rayon passant par F sort parallèlement à l’axe. Les deux premiers suffisent à déterminer l’image, le troisième contrôle le dessin."),
        P("Exemple.", "f′=100 mm et p=−300 mm donnent p′=150 mm et γ=−0,50. Avec p=−50 mm, p′=−100 mm et γ=2 : l’image virtuelle est droite et agrandie. Pour p=−f′ l’image est à l’infini ; aucune position finie d’écran ne peut la recueillir."),
        P("Validité.", "Conjugaison et grandissement supposent le régime paraxial de Gauss. Agrandir le diaphragme ne modifie pas cette formule idéale, mais modifie lumière collectée, diffraction et aberrations réelles. Les laboratoires correspondants explorent ces effets séparément.")),
    lesson("4. Newton et ABCD : composer les systèmes sans refaire tous les rayons", "Sup → Spé", "lentille",
        P("Deux écritures.", "Dans l’air, f=OF=−f′ et les distances depuis les foyers sont FA=p−f, F′A′=p′−f′. Pour les matrices paraxiales, le vecteur utilisé ici est (y, u) avec u=nθ, θ en radians. Cette coordonnée réduite évite de confondre une translation dans le verre avec une translation dans l’air."),
        F("FA·F′A′=ff′=−f′²\nT(d, n)=[[1, d/n],[0,1]] ; L(C)=[[1,0],[−C,1]]\n(y₂, u₂)ᵀ=M(y₁, u₁)ᵀ ; det M=1"),
        P("Calcul.", "Les matrices agissent de droite à gauche dans l’ordre de traversée. Entre un plan objet et un plan image, M=T(d₂,1)L(1/f′)T(d₁,1). La condition d’image est B=0 : tous les rayons de même hauteur objet donnent la même hauteur image indépendamment de leur pente initiale."),
        P("Invariant.", "Le déterminant unité exprime la conservation du produit symplectique y₁u₂−y₂u₁ entre deux rayons paraxiaux. Avec le vecteur (y, θ), le déterminant entre deux indices différents devient nentrée/nsortie : le choix des coordonnées doit donc précéder une assertion sur le déterminant."),
        P("Exemple.", "Deux lentilles de vergences C₁, C₂ séparées par d dans l’air ont Céquiv=C₁+C₂−dC₁C₂. C₁=10 δ, C₂=5 δ, d=0,10 m donnent Céquiv=10 δ, et non 15 δ. Les plans principaux se déplacent : la focale équivalente seule ne donne pas la position du foyer depuis chaque lentille.")),
    lesson("5. Bessel et Silbermann : déterminer une focale sans localiser son centre", "Sup ; TP", "bessel",
        P("Montage.", "Un objet et un écran sont séparés d’une distance D>0 fixe. Une lentille convergente mince se déplace entre eux. Noter x la distance positive objet→lentille, y=D−x la distance lentille→écran. Le grandissement algébrique est γ=−y/x."),
        F("1/x+1/(D−x)=1/f′\nx²−Dx+Df′=0 ; x±=(D±√(D²−4Df′))/2\nd=x+−x− ; f′=(D²−d²)/(4D)"),
        P("Seuil.", "Deux positions nettes existent pour D>4f′ ; elles se confondent pour D=4f′, cas de Silbermann avec γ=−1. Pour D<4f′, l’absence de mise au point sur cet écran est une conséquence de la géométrie et ne prouve pas que la lentille est divergente."),
        P("Exemple.", "D=800 mm, d=400 mm donnent f′=150 mm ; les positions depuis l’objet sont x=200 et 600 mm. Les grandissements sont −3 et −1/3 : leur produit vaut 1, ce qui offre un contrôle indépendant par mesure des tailles."),
        P("Méthode.", "Faire la netteté sur les mêmes détails fins, repérer les deux positions en approchant de chaque côté et estimer la largeur de la zone de netteté. Un diaphragme facilite parfois ce repérage mais augmente la profondeur de champ et peut rendre la position optimale moins précise.")),
    lesson("6. Bessel : propager l’incertitude et choisir D", "Sup → Spé ; TP", "bessel",
        P("Grandeurs mesurées.", "D et d sont des distances positives obtenues par des différences de positions sur le banc. Leurs incertitudes standards peuvent être corrélées si les mêmes lectures interviennent. Le laboratoire illustre l’effet d’un réglage ; l’analyse d’incertitude ci-dessous complète un compte rendu de TP."),
        F("f′=D/4−d²/(4D)\n∂f′/∂D=1/4+d²/(4D²) ; ∂f′/∂d=−d/(2D)\nu(f′)²=fD²u(D)²+fd²u(d)²+2fDfd cov(D, d)"),
        P("Exemple.", "D=800 mm, d=400 mm, u(D)=u(d)=1 mm et indépendance donnent fD=0,3125, fd=−0,25 et u(f′)≈0,400 mm. On rapporte f′=(150,0±0,4) mm avec l’incertitude standard explicitée, sans annoncer artificiellement plusieurs décimales."),
        P("Choix expérimental.", "Près de D=4f′, les positions fusionnent : la faible sensibilité algébrique à d ne signifie pas que d est facile à mesurer. Très loin du seuil, une image est petite et moins facile à observer. La qualité de netteté et la longueur du banc comptent autant que les dérivées."),
        P("Prolongement.", "Une simulation Monte-Carlo des lectures de positions teste l’approximation linéaire et traite une corrélation. L’incertitude du modèle mince, liée à l’épaisseur ou aux aberrations, ne se réduit pas en répétant indéfiniment les mêmes lectures.")),
    lesson("7. Lunette astronomique : grossissement et afocalité", "Sup ; TP", "telescope",
        P("Système.", "La lunette de Kepler comporte un objectif convergent de focale fo et un oculaire convergent de focale fe. Un objet astronomique est décrit par son angle α, non par une hauteur finie placée arbitrairement sur le banc. Quand F′objectif=Foculaire, la sortie est parallèle et l’œil observe sans accommodation."),
        F("d=fo+fe ; α′=−(fo/fe)α ; G=α′/α=−fo/fe\nhimage≈fo α ; Dsortie=Dobjectif/|G|"),
        P("Dérivation.", "L’objectif transforme l’angle α en une hauteur intermédiaire foα. L’oculaire transforme cette hauteur en un angle opposé, −h/fe. Le grossissement négatif indique une image renversée. Une lunette de Galilée emploie un oculaire divergent : son grossissement est positif et son écartement fo−|fe|."),
        P("Exemple.", "fo=1000 mm, fe=25 mm donnent G=−40 et d=1025 mm. Un détail de diamètre angulaire 1 minute d’arc devient apparent sous environ 40 minutes d’arc, soit 0,667°, dans l’approximation paraxiale. Un objectif de 80 mm donne une pupille de sortie de 2 mm."),
        P("TP.", "Régler d’abord l’oculaire sur le réticule, puis l’objectif sur un objet à l’infini. Le changement d’écartement dégrade l’afocalité : augmenter le grossissement affiché ne compense pas une mise au point incorrecte ni une pupille trop petite.")),
    lesson("8. De la Lune à l’étoile double : grossir, résoudre, échantillonner", "Sup → Spé", "telescope",
        P("Trois critères.", "Le grossissement change la taille angulaire apparente ; le diamètre collecteur change diffraction et flux ; le pixel du détecteur échantillonne l’image. Ces trois fonctions sont distinctes. Un télescope réfléchissant évite la dispersion d’une lentille principale mais conserve diffraction et aberrations géométriques."),
        F("θRayleigh≈1,22 λ₀/D ; séparation image=f θ\nchamp par pixel≈p/f ; collecte ∝D²"),
        P("Exemple.", "À λ₀=550 nm et D=0,20 m, θRayleigh≈3,355 μrad≈0,692 seconde d’arc. Avec f=2 m, la séparation correspondante vaut 6,71 μm au foyer. Un pixel de 10 μm sous-échantillonne cette échelle ; un pixel de 3 μm la représente avec plusieurs échantillons."),
        P("Observation réelle.", "La turbulence atmosphérique peut dominer la limite de diffraction ; une obstruction centrale redistribue la lumière dans les anneaux ; des sources de luminosités très différentes ne suivent pas exactement le critère simple de deux points égaux. Les expériences de résolution utilisent donc des hypothèses annoncées."),
        P("Bilan de chaîne.", "Doubler fo avec le même diamètre double les tailles au foyer et change l’échantillonnage, mais ne divise pas l’angle de Rayleigh par deux. Pour gagner réellement une résolution angulaire dans ce modèle, augmenter D ou diminuer λ₀.")),
    lesson("9. Microscope : image intermédiaire et puissance", "Sup ; TP", "microscope",
        P("Montage.", "L’objectif forme une image réelle agrandie d’un objet proche de son foyer objet. L’oculaire agit comme une loupe de cette image. On note Δ=F′objectif Foculaire l’intervalle optique et d₀=250 mm la distance conventionnelle de comparaison à l’œil nu."),
        F("γobjectif≈−Δ/fo ; Goculaire≈d₀/fe\nGcommercial≈−Δd₀/(fo fe) ; P=α′/AB≈−Δ/(fo fe)"),
        P("Signe et unités.", "La puissance P est en m⁻¹ car elle divise un angle sans dimension par une taille objet ; le grossissement commercial G est sans dimension. Une expression positive décrit souvent la valeur absolue : le microscope afocal produit ici une image renversée."),
        P("Exemple.", "Δ=160 mm, fo=4 mm et fe=25 mm donnent γobjectif≈−40, Goculaire≈10 et G≈−400. Un détail de 5 μm devient une hauteur intermédiaire de 0,20 mm puis un angle de 8 mrad, contre 20 μrad à l’œil nu à 25 cm."),
        P("TP.", "Placer l’image intermédiaire dans le plan focal objet de l’oculaire demande un réglage de netteté de l’objectif. Le modèle paraxial aide à comprendre la chaîne ; les objectifs à forte ouverture et les microscopes corrigés à l’infini demandent une description plus complète de la pupille et des lentilles de tube.")),
    lesson("10. Ouverture numérique : compter la résolution utile", "Spé ; prolongement instrumentation", "microscope",
        P("Définition.", "L’ouverture numérique NA=n sin u associe l’indice côté objet et le demi-angle du cône collecté. Elle décrit une capacité à collecter des directions et à transmettre des fréquences spatiales. Un fort grossissement avec une faible NA agrandit surtout un flou."),
        F("dRayleigh≈0,61 λ₀/NA ; dAbbe≈λ₀/(2NA)\nordre de grandeur axial : profondeur≈nλ₀/NA²"),
        P("Critères.", "0,61 et 1/2 correspondent à des questions différentes : séparation de points incohérents avec un critère de Rayleigh ou limite de transmission de détails périodiques selon illumination. Ne pas présenter les deux nombres comme deux mesures incompatibles d’une unique grandeur universelle."),
        P("Exemple.", "À 550 nm, NA=0,25 donne dRayleigh≈1,34 μm ; NA=1,25 donne environ 0,268 μm. La seconde valeur requiert un milieu d’immersion, puisque dans l’air NA≤1. Pour un grossissement objectif de 40, un pixel de 6,5 μm représente 0,1625 μm côté objet."),
        P("Technique.", "Ramener toutes les longueurs du détecteur au plan objet, puis comparer taille de pixel, tache et détail demandé. Une formule de résolution ne remplace pas le bilan de contraste, d’éclairement, d’aberration et de bruit d’une observation biologique ou physique.")),
    lesson("11. Œil réduit, accommodation et corrections", "Sup", "oeil",
        P("Modèle.", "Un œil réduit est une lentille convergente réglable suivie d’une rétine à distance fixe ℓ. Le modèle utilise ici un espace image assimilé à l’air pour isoler la conjugaison ; sa vergence effective ne représente pas directement toutes les surfaces de l’œil anatomique. L’objet est à distance positive s devant l’œil."),
        F("Crequise=1/ℓ+1/s ; pour l’infini Crequise=1/ℓ\nCcorrection≈1/ℓ−Cœil, relaxé ; addition de vergences pour lentilles en contact"),
        P("Exemple.", "ℓ=17 mm demande 58,82 δ pour l’infini et 62,82 δ pour un objet à 25 cm : l’accommodation supplémentaire vaut 4 δ. Un œil trop convergent de 2 δ se corrige dans ce modèle par −2 δ ; une accommodation limitée rend la lecture proche difficile."),
        P("Image.", "L’image rétinienne est réelle et renversée. Un objet de 10 mm à 1 m produit approximativement une hauteur de −0,17 mm. Le diaphragme pupillaire réduit le flou de défocalisation quand il se ferme, mais augmente la diffraction ; le diamètre optimal résulte d’un compromis."),
        P("Interprétation.", "Myopie, hypermétropie et presbytie correspondent ici à des modifications distinctes de convergence, géométrie ou plage d’accommodation. Le modèle sert à apprendre la conjugaison et ses ordres de grandeur ; il ne calcule pas une prescription individuelle.")),
    lesson("12. Fibre à saut d’indice : du rayon guidé au cône d’entrée", "Sup → Spé", "fibre",
        P("Géométrie.", "Le cœur a un indice n₁ supérieur à celui de la gaine n₂. Un rayon méridien fait l’angle θ avec l’axe et atteint la paroi sous l’incidence i=π/2−θ. À la face d’entrée normale à l’axe, le milieu extérieur a l’indice n₀."),
        F("sin ic=n₂/n₁ ; θ<arccos(n₂/n₁)\nn₀ sin θentrée, max=NA=√(n₁²−n₂²)\nV=(2πa/λ₀)NA ; monomode LP₀₁ si V<2,405 pour une fibre idéale faiblement guidante"),
        P("Dérivation.", "La réflexion totale demande n₁ sin i>n₂, soit n₁ cosθ>n₂. En combinant avec n₀ sinθentrée=n₁ sinθ on obtient le cône d’acceptance. Le rayon axial et les rayons très inclinés ne passent pas le même temps dans une fibre multimode."),
        P("Exemple.", "n₁=1,48, n₂=1,46 donnent NA≈0,2425 et θentrée, max≈14,03° dans l’air. Avec a=4 μm, λ₀=1,55 μm, V≈3,93 : le critère monomode n’est pas satisfait. Le seuil sur le rayon est a<2,405λ₀/(2πNA)≈2,45 μm."),
        P("Deux niveaux.", "La réflexion totale décrit la trajectoire de rayons quand le cœur est grand devant λ. Le nombre V et le seuil 2,405 appartiennent au problème d’onde cylindrique : ils ne sont pas déduits par le seul dessin d’un rayon. Une fibre courbée, lossy ou fortement guidante demande d’autres corrections.")),
    lesson("13. Fibre à gradient : réduire la dispersion intermodale", "Spé → Au-delà accompagné", "fibre",
        P("Idée.", "Un cœur dont l’indice décroît depuis l’axe courbe progressivement les rayons. Les trajectoires éloignées sont plus longues mais parcourent un milieu de vitesse supérieure. Un profil parabolique peut compenser au premier ordre ces deux effets, contrairement au cœur uniforme."),
        F("n(r)≈naxe[1−g²r²/2] ; r″(z)+g²r(z)≈0\nr(z)=r₀ cos(gz)+(θ₀/g)sin(gz) ; période≈2π/g\nt≈(1/c)∫n(r)√(1+r′²) dz"),
        P("Démonstration.", "Dans la limite paraxiale, d(nu)/ds=∇n conduit à r″≈(1/n)∂rn≈−g²r. Pour comparer les temps, garder à la fois le terme d’indice et √(1+r′²)≈1+r′²/2 : supprimer l’un des deux empêche précisément la compensation recherchée."),
        P("Comparaison.", "Dans une fibre à saut d’indice uniforme de longueur L, tθ≈n₁L/(c cosθ). Pour L=1 km, n₁=1,48 et θ=10°, l’excès par rapport à l’axe est environ 76,2 ns. Il suffit à élargir une impulsion courte même si aucun rayon ne fuit."),
        P("Limites.", "Le modèle de rayons ne décrit pas la dispersion chromatique, la dispersion de polarisation ni les pertes. Les résultats sur les trajectoires et l’acceptance sont complémentaires de la propagation d’un paquet d’ondes dans l’atelier Champs et Matière.")),
    lesson("14. Mirage : un invariant et une trajectoire parabolique", "Sup → Spé", "mirage",
        P("Profil étudié.", "L’exemple du recueil est n(z)=n₀√(1+z/a), avec a>0 et z>−a. θ est l’angle du rayon avec l’horizontale ; x est la distance horizontale. Un indice croissant avec z courbe le rayon vers les couches hautes et peut donner une image de sol réfléchissant."),
        F("n(z)cosθ=n(z₀)cosθ₀ ; z′=tanθ\nz″=1/[2(a+z₀)cos²θ₀]\nz(x)=z₀+x tanθ₀+x²/[4(a+z₀)cos²θ₀]"),
        P("Dérivation.", "L’invariance par translation horizontale conserve la composante horizontale du vecteur n u. En élevant au carré, 1+z′²=(a+z)/[(a+z₀)cos²θ₀]. Dériver donne une accélération verticale constante ; intégrer deux fois fixe le coefficient quadratique et les deux conditions initiales."),
        P("Exemple.", "a=1000 m, z₀=1 m, θ₀=−1° donnent un point bas à x*=−2(a+z₀)cos²θ₀ tanθ₀≈34,94 m et zmin≈0,695 m. À x≈69,88 m, le rayon revient à son altitude de départ. Ce modèle stylisé ne remplace pas un profil atmosphérique mesuré."),
        P("Interprétation.", "Au point bas θ=0, la courbure est finie : on ne doit pas diviser aveuglément par z′=0 dans la dérivation. L’observateur prolonge la tangente à l’arrivée ; c’est ce prolongement rectiligne, distinct du rayon courbe, qui donne une position apparente.")),
    lesson("15. Arc-en-ciel : une caustique plutôt qu’un rayon privilégié", "Sup → Spé", "arcenciel",
        P("Modèle.", "Une goutte sphérique d’indice n dans l’air réfracte la lumière à l’entrée, effectue p réflexions internes puis la réfracte à la sortie. i et r sont les angles à la normale. Le rayon primaire correspond à p=1 ; le secondaire à p=2."),
        F("sin i=n sin r ; Dp=pπ+2i−2(p+1)r\nD′p=2−2(p+1)cos i/(n cos r)\nsin² i*=[(p+1)²−n²]/[(p+1)²−1]"),
        P("Stationnarité.", "Des incidences voisines donnent presque la même déviation lorsque D′p=0 : les rayons se concentrent angulairement, ce qui produit une caustique. La divergence du modèle géométrique est régularisée par la diffraction et la taille finie de la source."),
        P("Exemple.", "Pour n=4/3 et p=1, i*≈59,39°, r*≈40,20° et Dmin≈137,97°. Le rayon du cercle primaire autour du point antisolaire vaut π−Dmin≈42,03°. Pour p=2, la déviation stationnaire dépasse π et donne un rayon secondaire voisin de 51°. La seconde réflexion réduit l’intensité."),
        P("Dispersion.", "Au point stationnaire primaire, ∂D/∂n=4tanr/n. Le violet, de plus grand indice, a une déviation D supérieure donc un rayon antisolaire inférieur : il est à l’intérieur du primaire. Le secondaire inverse l’ordre. Les coefficients de Fresnel rendent aussi les arcs partiellement polarisés.")),
    lesson("16. Prisme et goniomètre : mesurer une dispersion", "Sup ; TP", "prisme",
        P("Montage.", "Un collimateur donne une onde quasi plane ; une lunette afocale repère l’angle de sortie. A est l’angle au sommet du prisme ; i, r sont les angles d’entrée, r′, i′ ceux de sortie. Les indices d’entrée et de sortie sont ceux de l’air dans le modèle."),
        F("r+r′=A ; D=i+i′−A ; sin i=n sin r\nDmin=2arcsin[n sin(A/2)]−A\nn=sin[(A+Dmin)/2]/sin(A/2) ; n(λ₀)=a+b/λ₀²"),
        P("Démonstration.", "Différencier la loi de Snell aux deux faces avec dr′=−dr. La déviation stationnaire est obtenue pour le trajet symétrique i=i′, r=r′=A/2. Vérifier n sin(A/2)≤1 : si cette condition échoue, la transmission à ce trajet est impossible."),
        P("Exemple.", "A=60°, n=1,50 donnent Dmin≈37,18°. Inversement, Dmin=40° donne n≈1,5321. Pour mesurer l’indice, suivre le retournement de déplacement de la raie lorsque le prisme tourne, plutôt que chercher le minimum par une unique lecture."),
        P("Cauchy.", "La constante b a les unités de λ₀² ; une valeur donnée en μm² doit être convertie si λ est exprimée en nm. Ajuster n en fonction de 1/λ₀² donne une droite dans une fenêtre transparente limitée ; cette loi empirique ne s’étend pas arbitrairement aux résonances d’absorption.")),
    lesson("17. Aberrations : la sphère face au paraboloïde", "Sup → Spé ; prolongement conception", "aberrations",
        P("Deux modèles.", "La conjugaison du miroir sphérique résume une limite paraxiale. Le laboratoire compare les réflexions géométriques exactes d’un faisceau axial sur une sphère et sur un paraboloïde. Le sommet est x=0, le centre sphérique x=−R, le faisceau arrive depuis x<0 vers +x ; le foyer paraxial est x=−R/2."),
        F("Sphère : x(y)=−R+√(R²−y²) ; parabole : x(y)=−y²/(2R)\nvsortie=vincident−2(vincident·n̂)n̂\nFoyer axial du paraboloïde : xF=−R/2"),
        P("Aberration sphérique.", "Pour la sphère, les rayons de hauteurs différentes ne coupent pas l’axe au même endroit. Fermer l’ouverture rapproche la surface de sa approximation parabolique : x=−y²/(2R)−y⁴/(8R³)+… . Le cercle de moindre diffusion n’est pas toujours au foyer paraxial. Le calcul exact reste un calcul de rayons : aucun anneau de diffraction n’y est simulé."),
        P("Stigmatisme axial.", "Le paraboloïde rend égaux les chemins optiques d’un front plan axial vers F : sa normale bisecte la direction incidente et celle du foyer. Il est donc stigmatique pour cet objet à l’infini sur l’axe, même à grande ouverture géométrique. Une source hors axe peut cependant produire de la coma ; ce succès ne rend pas toutes ses images parfaites."),
        P("Technique.", "Déplacer l’écran et comparer l’écart des interceptions à ouverture fixée. Fermer le diaphragme réduit l’erreur géométrique mais augmente la diffraction de l’atelier Airy. Pour une lentille, un autre effet s’ajoute : n(λ) variable donne un chromatisme ; il est absent de la réflexion idéale de ces miroirs.")),
    lesson("18. Fermat : calculer un chemin stationnaire", "Sup → Spé ; calcul variationnel accompagné", "fermat",
        P("Fonction étudiée.", "Entre A et B de part et d’autre d’une interface plane, le point de traversée a l’abscisse x. Les hauteurs positives sont h₁, h₂ et la séparation horizontale totale est X. La durée est le chemin optique L divisé par c."),
        F("L(x)=n₁√(x²+h₁²)+n₂√[(X−x)²+h₂²]\nL′=n₁ x/√(x²+h₁²)−n₂(X−x)/√[(X−x)²+h₂²]\nL′=0 ⇔ n₁sin i=n₂sin r"),
        P("Unicité ici.", "L″=n₁h₁²/(x²+h₁²)³ᐟ²+n₂h₂²/[(X−x)²+h₂²]³ᐟ²>0 : cette configuration donne un minimum unique. Dans un système optique général, le principe est celui d’une stationnarité ; des maxima ou selles peuvent intervenir. La convexité doit être prouvée pour parler de minimum."),
        P("Exemple.", "Pour n₁=n₂ et h₁=h₂, la symétrie donne x=X/2. Si n₂ augmente, le rayon parcourt moins de distance horizontale dans le second milieu : le passage se déplace vers B. La trajectoire la plus rapide n’est plus le segment euclidien le plus court."),
        P("Lien interdisciplinaire.", "Optimisation, convexité, équations d’Euler–Lagrange et intégrales premières sont les mêmes outils que dans l’atelier Distances. Dans un indice variable, la fonctionnelle ∫n ds donne d(nu)/ds=∇n, ce qui relie Fermat, Snell et le mirage.")),
]

LESSONS += [
    lesson("19. Interférer : sommer les amplitudes, moyenner les intensités", "Sup → Spé", "young",
        P("Notations.", "Deux champs de même fréquence et de même polarisation ont des amplitudes complexes A₁, A₂. Les intensités individuelles I₁, I₂ sont proportionnelles à |A₁|²,|A₂|². Le détecteur moyenne sur un temps grand devant la période optique ; il ne moyenne pas automatiquement à zéro une différence de phase stable."),
        F("I=I₁+I₂+2√(I₁I₂) cosφ\nImax=(√I₁+√I₂)² ; Imin=(√I₁−√I₂)²\nV=(Imax−Imin)/(Imax+Imin)=2√(I₁I₂)/(I₁+I₂)"),
        P("Cohérence.", "La formule suppose une différence de phase stable. Pour des sources mutuellement indépendantes, la moyenne du terme croisé est nulle et I=I₁+I₂. Des polarisations orthogonales annulent aussi le produit scalaire des champs, même si leur fréquence est identique."),
        P("Exemple.", "I₂=I₁/4 donne V=0,80, Imax=2,25I₁ et Imin=0,25I₁. Une frange noire n’est possible qu’avec amplitudes égales, cohérence complète et polarisation compatible. La visibilité peut donc diminuer sans modification de l’interfrange."),
        P("Bilan.", "Un maximum local de 4I₁ pour deux faisceaux égaux ne crée pas d’énergie : le champ redistribue le flux entre régions brillantes et sombres. Pour un dispositif complet, les sorties complémentaires et la normalisation spatiale doivent entrer dans le bilan.")),
    lesson("20. Young réel : deux longueurs, deux échelles", "Sup → Spé", "young",
        P("Géométrie.", "Les centres des fentes sont séparés de a ; chaque fente a une largeur b. Le plan d’observation est à distance D et la coordonnée transverse est x. Les directions sont paraxiales, les fentes sont uniformément éclairées et l’observation se fait en Fraunhofer, ou dans un plan focal équivalent."),
        F("δ≈ax/D ; i=λ₀D/a\nI(x)∝sinc²[πbx/(λ₀D)]·[1+ρ+2√ρ cos(2πax/(λ₀D)+φ₀)]\nsinc u=sin u/u ; sinc 0=1 ; largeur totale du lobe central=2λ₀D/b"),
        P("Lecture.", "a contrôle l’interfrange ; b contrôle l’enveloppe. Doubler a divise i par deux sans rétrécir l’enveloppe. Doubler b resserre l’enveloppe sans changer les positions idéales des franges. ρ=I₂/I₁ contrôle leur contraste, φ₀ leur translation."),
        P("Exemple.", "λ₀=600 nm, D=2 m, a=0,50 mm donnent i=2,40 mm. Avec b=0,040 mm, les premiers zéros de diffraction sont à x=±30 mm. L’ordre interférentiel k=25 coïncide avec un zéro d’enveloppe ; ce maximum est manquant."),
        P("Technique.", "Construire la différence de marche avant d’utiliser cos. Le signe de δ ou de φ dépend de l’ordre des trajets ; avec cos, une inversion simultanée ne change pas I. La phase additionnelle d’une lame, d’une translation ou d’une polarisation peut déplacer les franges.")),
    lesson("21. Réseau : somme géométrique et pouvoir de résolution", "Spé", "reseau",
        P("Objets.", "N fentes uniformes de largeur b et de pas d sont éclairées sous θ₀. La direction θ donne une différence de marche d(sinθ−sinθ₀). Les raies d’un doublet spectral indépendant s’additionnent en intensité ; elles ne sont pas deux amplitudes cohérentes à une seule fréquence."),
        F("φ=2πd(sinθ−sinθ₀)/λ₀ ; A∝∑p=0…N−1 exp(ipφ)\nI∝sinc²[πb(sinθ−sinθ₀)/λ₀]·[sin(Nφ/2)/sin(φ/2)]²\nd(sinθm−sinθ₀)=mλ₀ ; Rrésolution=λ₀/Δλ≈|m|N"),
        P("Singularités.", "À φ=2πm, le quotient se prolonge par N en amplitude, N² en intensité. Les zéros proches sont à φ=2πm±2π/N. Cette largeur diminue avec N tandis que la séparation des raies augmente avec |m| : leur comparaison donne le critère mN."),
        P("Exemple.", "Le doublet 589,0/589,6 nm a λ/Δλ≈982. À l’ordre 1 il faut environ 982 fentes éclairées ; à l’ordre 2 environ 491. Un pas d=2 μm permet l’ordre 2 autour de sinθ≈0,589 ; certains ordres plus élevés sont absents si |sinθm|>1."),
        P("Limites.", "Une enveloppe de fente peut supprimer un ordre pourtant géométriquement autorisé. Éclairage non uniforme, largeur de source, aberrations et résolution du détecteur modifient la résolution effective. R=λ/Δλ est un pouvoir spectral sans dimension, distinct d’une séparation spatiale minimale.")),
    lesson("22. Fraunhofer : intégrer une pupille rectangulaire", "Spé ; TP", "diffraction",
        P("Champ.", "La diffraction scalaire associe à chaque élément de pupille une amplitude et une phase. En champ lointain ou au foyer d’une lentille, la phase est linéaire en coordonnées de pupille. a, b sont les dimensions du rectangle ; fx, fy sont les fréquences spatiales en m⁻¹."),
        F("A(fx, fy)∝∫−a/2ᵃ/² ∫−b/2ᵇ/² t(x, y)e^(−2πi(fx x+fy y)) dxdy\nt=1 ⇒ A∝ab sinc(πa fx)sinc(πb fy)\nfx≈X/(λ₀f′) ; I/I(0)=sinc²(πaX/(λ₀f′))sinc²(πbY/(λ₀f′))"),
        P("Calcul.", "Séparer l’intégrale bidimensionnelle en produit de deux intégrales. ∫−a/2ᵃ/² exp(−ikx)dx=a sinc(ka/2). Le carré intervient après la somme complexe. Inverser cette succession supprimerait les interférences entre les éléments de pupille."),
        P("Exemple.", "a=0,20 mm, b=0,80 mm, f′=300 mm, λ₀=600 nm donnent des premiers zéros à X=±0,90 mm, Y=±0,225 mm. La petite dimension de pupille produit la grande dimension de tache : l’image diffractée croise l’orientation intuitive du trou."),
        P("Régime.", "Un écran éloigné demande un nombre de Fresnel a²/(λ₀D) suffisamment petit pour l’approximation lointaine. Le plan focal d’une lentille réalise la transformée de Fourier sous les hypothèses paraxiales. a≪D seul ne suffit pas à garantir Fraunhofer.")),
    lesson("23. Apodisation cosinus : réduire les lobes a un coût", "Spé → Au-delà accompagné", "diffraction",
        P("Pupille.", "Sur |x|≤a/2, la transmittance d’amplitude est t(x)=cos(πx/a) ; elle est nulle ailleurs. Elle ne transmet pas uniformément et son carré décrit la transmission locale de puissance. La variable u=πa sinθ/λ₀ sert à comparer avec la fente uniforme."),
        F("A(u)∝a·(π/2) cosu/(π²/4−u²)\nA(u)/A(0)=(π²/4) cosu/(π²/4−u²)\nPremiers zéros : u=±3π/2 ; u=±π/2 est une singularité amovible"),
        P("Dérivation.", "Écrire cos(πx/a) comme la somme de deux exponentielles : l’amplitude est la somme de deux sinc décalés. À u=±π/2, numérateur et dénominateur s’annulent mais leur rapport est fini ; remplacer cette valeur par zéro créerait un faux minimum."),
        P("Compromis.", "La demi-largeur du lobe central est 3λ₀/(2a), contre λ₀/a pour la fente uniforme. La puissance transmise à éclairage uniforme est ∫cos²(πx/a)dx=a/2, soit la moitié de celle d’une fente ouverte de même largeur. Une normalisation à I(0)=1 masque cette perte."),
        P("Exemple.", "a=1 mm, λ₀=600 nm donnent les premiers zéros à ±0,900 mrad ; à u=π/2, I/I(0)=π²/16≈0,617. Le passage de lobes secondaires faibles à un pic plus large illustre un compromis général de fenêtrage en optique et en traitement du signal.")),
    lesson("24. Polarisation : Malus, ellipse et lame à retard", "Sup → Spé selon filière", "polarisation",
        P("Mesure.", "Un analyseur linéaire d’axe â projette le champ sur cet axe. Pour un état rectiligne d’angle θ avec l’analyseur, I=I₀cos²θ. Une intensité constante quand on tourne l’analyseur peut correspondre à un état circulaire ou à une lumière non polarisée ; une lame quart d’onde permet de les distinguer."),
        F("Ex=Ax cosωt ; Ey=Ay cos(ωt−δ)\nδlame=2πΔn e/λ₀ ; quart d’onde : |δ|=π/2 ; demi-onde : |δ|=π\nLame idéale sans pertes ⇒ |Ex|²+|Ey|² conservé"),
        P("Quart d’onde.", "Une entrée rectiligne à 45° des axes propres et une retardance ±π/2 donnent deux composantes égales en quadrature : un cercle. Une entrée alignée sur un axe propre reste rectiligne. Le signe de la rotation dépend de la convention temporelle et du sens d’observation."),
        P("Demi-onde.", "Une entrée rectiligne d’angle θ face à un axe propre d’angle α ressort rectiligne d’angle 2α−θ modulo π. La lame conserve l’intensité ; la transmission de l’analyseur peut ensuite varier jusqu’à l’extinction."),
        P("TP.", "Commencer par caractériser la source à l’analyseur seul, introduire la lame et chercher ses axes, puis interpréter les minima et maxima. La couleur, les pertes et l’achromatisme limitent la description d’une lame par une unique retardance indépendante de λ.")),
    lesson("25. Jones et Poincaré : calcul matriciel et état physique", "Spé → Au-delà accompagné", "polarisation",
        P("Convention.", "Le champ réel est Re[Ẽ exp(−iωt)]. Jones décrit un état monochromatique complètement polarisé par un vecteur complexe (Ex, Ey). Dans sa base propre la lame applique diag(1, exp(iδ)) ; une rotation réelle ramène ce vecteur dans les axes du banc."),
        F("J(α, δ)=R(α)diag(1, e^(iδ))R(−α)\nIanalyseur=|Ex cosβ+Ey sinβ|²\nS₀=|Ex|²+|Ey|² ; S₁=|Ex|²−|Ey|² ; S₂=2Re(Ex*Ey) ; S₃=2Im(Ex*Ey)"),
        P("Sphère.", "Pour un état pur, S₁²+S₂²+S₃²=S₀². Les états rectilignes sont sur l’équateur S₃=0 et les deux quadratures circulaires aux pôles. Une phase globale exp(iφ) n’altère ni ellipse ni Stokes. Les angles de l’orientation rectiligne sont doublés sur l’équateur."),
        P("Exemple.", "(Ex, Ey)=(1, i)/√2 donne (S₁, S₂, S₃)=(0,0,1), une transmission de 1/2 par tout analyseur linéaire. Une lame quart d’onde convenable convertit cet état en rectiligne et rend une extinction possible."),
        P("Lien quantique.", "Une polarisation d’un photon a le même espace complexe à deux composantes qu’un qubit ; la sphère de Poincaré correspond alors à une sphère de Bloch avec conventions d’axes annoncées. Une lumière partiellement polarisée demande Stokes ou une matrice de cohérence : un seul vecteur Jones ne suffit pas.")),
    lesson("26. Michelson : le facteur deux et les franges localisées", "Spé ; TP", "michelson",
        P("Montage.", "La séparatrice crée deux trajets d’une même source ; les miroirs les renvoient à la séparatrice. Le déplacement axial e d’un miroir modifie un aller-retour. Une compensatrice égalise les traversées de verre quand le spectre est large."),
        F("Lame d’air : δ=2e cos i ; p=2e cos i/λ₀\nPetit angle au foyer : r≈f′i ; δ≈2e−e r²/f′²\nCoin d’air de petit angle α : δ(x)≈δ₀+2αx ; interfrange≈λ₀/(2α)"),
        P("Deux figures.", "Les anneaux d’égale inclinaison se lisent dans un plan focal : i y est transformé en une distance radiale. Les franges d’égale épaisseur du coin s’observent dans un plan image adapté. Les deux axes de graphique n’ont donc pas le même rôle physique."),
        P("Mesure.", "Une translation Δe fait défiler N≈2Δe/λ₀ franges en un point fixé. À 546 nm, Δe=100 μm correspond à environ 366 franges. Dans la lame d’air, deux anneaux brillants voisins ont une différence de rayons au carré de λ₀f′²/e dans l’approximation des petits angles."),
        P("Lumière blanche.", "Un spectre large concentre la visibilité près de la différence de marche nulle. La couleur des franges demande de sommer les contributions spectrales ; l’atelier monochromatique montre la géométrie, et le laboratoire Cohérence traite séparément l’enveloppe spectrale.")),
    lesson("27. Cohérence temporelle : transformer un spectre en visibilité", "Spé", "coherence",
        P("Corrélation.", "La différence de marche δ introduit le retard τ=δ/c dans l’air. Pour des intensités égales, la visibilité est le module de la cohérence γ(τ). Le spectre S(ν) est une densité positive de puissance ; ses composantes indépendantes se somment en intensité."),
        F("γ(τ)=∫S(ν)e^(2πiντ)dν / ∫S(ν)dν ; V=|γ|\nS gaussien de largeur FWHM Δν ⇒ V=exp[−π²Δν²τ²/(4ln2)]\nDeux raies égales ν₁, ν₂ ⇒ V=|cos[π(ν₂−ν₁)τ]|"),
        P("Échelles.", "La formule τc≈1/Δν donne un ordre de grandeur, mais un temps à 1/e, à moitié visibilité ou une largeur intégrale diffèrent par des facteurs numériques. Toujours déclarer le profil spectral et le seuil utilisé avant de comparer deux longueurs de cohérence."),
        P("Exemple.", "Pour Δν=20 GHz, le spectre gaussien atteint V=1/2 à δ=2ln2·c/(πΔν)≈6,62 mm. Un doublet étroit montre au contraire des annulations puis des retours de contraste ; une première annulation ne mesure pas sa largeur intrinsèque de raie."),
        P("Technique.", "Travailler en fréquence pour une transformée en retard. Une petite largeur en longueur d’onde vérifie Δν≈cΔλ/λ₀² ; convertir un spectre large de Sλ à Sν demande aussi le jacobien |dλ/dν|.")),
    lesson("28. Source étendue et doublet : deux pertes de contraste différentes", "Spé ; TP", "coherence",
        P("Étendue.", "Une source uniforme de largeur s à distance Ds éclaire deux fentes séparées de a. Deux points sources sont pris mutuellement indépendants. Chacun produit des franges décalées ; leur somme peut effacer le contraste sans effacer la puissance reçue."),
        F("γspatial=sinc[πas/(λ₀Ds)] ; Vspatial=|γspatial|\nSous hypothèses séparables : V=|γtemporel γspatial|\nDoublet : première annulation δ≈λ₀²/(2Δλ) ; période de |V|≈λ₀²/Δλ"),
        P("Exemple.", "Avec λ₀=600 nm, a=0,50 mm, Ds=1 m, le premier zéro spatial est à s=1,20 mm. Une source ponctuelle lève cet effet mais n’annule pas la largeur spectrale. Pour le sodium autour de 589,3 nm et Δλ=0,60 nm, la première annulation temporelle est vers 0,289 mm."),
        P("Michelson.", "Au voisinage de l’incidence normale, δ≈2e ; les annulations du doublet sont espacées de Δe≈λ₀²/(2Δλ). Ce facteur deux ne doit pas être confondu avec la demi-période qui situe la première annulation depuis le contact."),
        P("Protocole.", "À δ fixé, varier s puis Ds et suivre a s/Ds. À source spatialement fine, balayer δ et comparer gaussien et doublet. Conserver les deux trajets mais sélectionner des sources indépendantes fait disparaître le terme croisé à tout retard dans le modèle.")),
    lesson("29. Fabry–Perot : additionner une infinité de trajets", "Spé → Au-delà accompagné", "fabryperot",
        P("Cavité.", "Deux miroirs plans parallèles identiques encadrent une lame d’épaisseur e et d’indice n. R est leur réflectivité de puissance, T=1−R en absence de pertes. θ est l’angle interne ; la longueur d’onde λ₀ est celle du vide."),
        F("φ=4πne cosθ/λ₀ ; Atransmis∝T/(1−R e^(iφ))\nIt/Iincident=1/[1+F sin²(φ/2)] ; F=4R/(1−R)²\nφ=2πm ⇒ transmission=1 pour deux miroirs identiques sans pertes"),
        P("Dérivation.", "Chaque aller-retour multiplie l’amplitude par R exp(iφ), car deux facteurs de réflexion d’amplitude de module √R interviennent. La série converge pour R<1. À résonance, les contributions se renforcent malgré la faible transmission d’un miroir isolé."),
        P("Exemple.", "R=0,90 donne F=360 et Tmin=1/(1+F)≈0,00277. Le contraste spectral est élevé, mais les résonances se répètent à chaque ordre : un filtre d’ordre peut être nécessaire pour isoler une raie unique."),
        P("Convention.", "Le coefficient d’Airy F et la finesse spectrale ne sont pas le même nombre. Des miroirs inégaux, des pertes, une absorption ou une phase de réflexion dispersive réduisent et déplacent les pics. Le modèle idéal utilise ici une cavité vide de pertes et un balayage quasi statique.")),
    lesson("30. Fabry–Perot : intervalle libre, finesse et angle", "Spé → Au-delà accompagné", "fabryperot",
        P("Mesures.", "L’intervalle spectral libre sépare deux résonances consécutives en fréquence. La finesse ℱ est ce même intervalle divisé par la largeur FWHM d’un pic. Les expressions simples supposent un indice constant sur la fenêtre ; en milieu dispersif l’indice de groupe remplace l’indice de phase pour l’intervalle."),
        F("FSR=c/(2ne cosθ) ; ℱ=π/[2arcsin(1/√F)] si F≥1\nR proche de 1 : ℱ≈π√R/(1−R) ; ΔνFWHM=FSR/ℱ\nνm(θ)=mc/(2ne cosθ)"),
        P("Exemple.", "Dans l’air, e=5 mm et R=0,90 donnent FSR≈29,98 GHz,ℱ≈29,79 et Δν≈1,01 GHz. Augmenter e rapproche les ordres sans changer cette finesse idéale ; augmenter R resserre les pics en réduisant la largeur relative."),
        P("Angle.", "Une direction inclinée a cosθ<1 : sa fréquence résonante augmente pour un ordre fixé, tandis que la longueur d’onde résonante diminue. Une distribution angulaire large mélange des fréquences de résonance différentes et peut élargir un pic."),
        P("Technique.", "Pour comparer deux raies, exprimer Δλ et Δν dans la même fenêtre locale puis examiner largeur, ordre et contraste. Un pic fin ne garantit pas l’absence d’ambiguïté d’ordre. Les oscillations de cavité expliquent aussi la sélection longitudinale d’un laser.")),
    lesson("31. Optique de Fourier : de la lentille au filtrage 4f", "Spé → Au-delà accompagné", "fourier",
        P("Chaîne.", "Un objet complexe Eobjet(x, y) est placé dans le plan focal objet d’une lentille. Son plan focal image porte, à un facteur de phase et d’échelle près, sa transformée de Fourier. Un masque H(fx, fy) placé là filtre les amplitudes ; une seconde lentille reconstruit un champ image."),
        F("XFourier=λ₀ f′ fx ; YFourier=λ₀ f′ fy\nEimage=TF⁻¹[H·TF(Eobjet)] ; Iimage=|Eimage|²\nTF E(f)=∫E(x)e^(−2πifx)dx"),
        P("Lecture.", "Un masque passe-bas réduit les hautes fréquences spatiales, donc les détails fins ; un passe-haut accentue les transitions mais modifie leur champ et leur intensité. Une fente verticale du plan de Fourier restreint fx et agit sur la variation horizontale de l’image."),
        P("Exemple.", "Avec λ₀=600 nm, f′=200 mm, une fréquence de 20 mm⁻¹ se trouve à 2,40 mm de l’axe dans le plan de Fourier. Doubler f′ double cette position sans modifier la fréquence spatiale de l’objet."),
        P("Précision.", "Filtrer une image d’intensité comme un signal réel n’est pas la même opération que filtrer son champ complexe cohérent puis le mettre au carré. Le laboratoire suit cette deuxième chaîne. Deux transformées directes réalisent une inversion spatiale ; l’écriture avec TF⁻¹ utilise des coordonnées image redressées.")),
    lesson("32. Fourier numérique : phase, Parseval et échantillonnage", "Spé → Au-delà accompagné", "fourier",
        P("Objet.", "Le champ peut avoir une amplitude uniforme mais une phase variable. Son intensité de départ est alors uniforme, tandis que son spectre complexe contient les variations de phase. Un filtre peut convertir une partie de ces variations en contraste d’intensité."),
        F("Eobjet=A e^(iφ(x, y)) ; FFT unitaire ⇒ ∑|E|²=∑|Ẽ|²\n|H|≤1 ⇒ ∑|Eimage|²≤∑|Eobjet|²\nfNyquist=1/(2Δx) ; Δf=1/(NΔx)"),
        P("Exemple.", "Un pas Δx=10 μm donne fNyquist=50 mm⁻¹. Une fréquence physique de 80 mm⁻¹ ne peut pas être représentée fidèlement par cette grille : elle replie sur une fréquence plus basse. Le réglage d’un masque au-delà de Nyquist n’ajoute pas des détails absents."),
        P("Bilan.", "Le filtre identité conserve la norme totale du champ ; un masque opaque perd de l’énergie. Une image dont chaque affichage est séparément renormalisé peut sembler aussi lumineuse dans les deux cas : le bilan chiffré, distinct de la palette de visualisation, empêche cette confusion."),
        P("Limites.", "La grille finie correspond à un objet périodisé dans le calcul ; les contours et les bords peuvent introduire des fréquences. Une convolution de PSF convient à l’imagerie incohérente, mais ce laboratoire simule une propagation et un filtrage de champ cohérent.")),
    lesson("33. Laser : stabilité de cavité et seuil de gain", "Spé → Au-delà accompagné", "laser",
        P("Deux questions.", "Le mot laser désigne une amplification par émission stimulée avec retour de cavité. Un confinement géométrique stable fournit des modes transverses ; il faut ensuite que le gain compense les pertes pour l’oscillation. Une cavité stable sans inversion de population n’est pas un laser actif."),
        F("g₁=1−L/R₁ ; g₂=1−L/R₂ ; zone stable intérieure : 0<g₁g₂<1\nMultiplicateur de puissance aller-retour : Rmiroir1 Rmiroir2 exp[2(g−α)L]\ngseuil=α−ln(Rmiroir1 Rmiroir2)/(2L)"),
        P("Variables.", "R₁, R₂ dans g₁, g₂ sont des rayons de courbure signés, tandis que Rmiroir sont des réflectivités sans dimension. Le laboratoire règle des courbures 1/R en m⁻¹, pour représenter aussi un miroir plan. g et α sont ici des coefficients de gain et de perte d’intensité en m⁻¹."),
        P("Saturation.", "Avec le modèle g(P)=g₀/(1+P/Ps), le régime établi impose g(P)=gseuil, d’où P=Ps(g₀/gseuil−1) quand g₀>gseuil. La puissance transmise au coupleur est approximativement (1−Rmiroir2)P. La pompe fournit l’énergie, la cavité la redistribue."),
        P("Limites.", "Les frontières de stabilité sont marginales ; des configurations dégénérées demandent un examen spécifique, notamment le confocal. Le modèle de saturation ne décrit ni compétition multimode, ni dynamique de population, ni largeur de raie ou bruit. Les modes longitudinaux sont espacés approximativement de c/(2nL).")),
    lesson("34. Faisceau gaussien : conserver la puissance en divergeant", "Spé → Au-delà accompagné", "gaussien",
        P("Notations.", "w(z) est le rayon où l’intensité vaut 1/e² de sa valeur axiale, non un diamètre. w₀ est le waist au plan z=0. Le milieu est homogène d’indice n ; λ₀ est dans le vide. Le faisceau fondamental paraxial TEM₀₀ ne représente pas tout faisceau laser réel."),
        F("zR=πn w₀²/λ₀ ; w(z)=w₀√[1+(z/zR)²]\nI(r, z)=2P/[πw(z)²] exp[−2r²/w(z)²] ; θdiv≈λ₀/(πn w₀)\nRfront=z[1+(zR/z)²] ; ψGouy=arctan(z/zR)"),
        P("Intégrale.", "La puissance est 2π∫₀∞I r dr=P à tout z. Le maximum diminue quand le faisceau s’élargit ; la puissance ne diminue pas dans ce modèle sans pertes. Au waist Rfront est infini, donc le front est localement plan malgré une divergence future finie."),
        P("Exemple.", "w₀=50 μm, λ₀=633 nm, n=1 donnent zR≈12,41 mm et θdiv≈4,03 mrad. À z=zR, w=w₀√2 et Iaxe est divisée par deux. Avec P=2 mW, Iaxe(0)≈5,09×10⁵ W·m⁻²."),
        P("Lien.", "Focaliser davantage diminue w₀ mais augmente la divergence et réduit zR quadratiquement. Avec les matrices du vecteur (y, θ), q=z+izR obéit à q′=(Aq+B)/(Cq+D), et 1/q=1/Rfront−iλ₀/(πn w²). Pour utiliser à la place le vecteur réduit (y, nθ) de la leçon 4, prendre le paramètre qréduit=q/n, qui suit cette même loi homographique avec ses matrices réduites. Le choix des coordonnées demeure cohérent de la translation au faisceau.")),
    lesson("35. Airy : une pupille circulaire et deux étoiles indépendantes", "Spé → Au-delà accompagné", "airy",
        P("Pupille idéale.", "Un disque circulaire uniformément éclairé de diamètre D produit une fonction de Bessel J₁. Les exemples astronomiques du laboratoire sont des pupilles circulaires idéales ; ils ne reproduisent pas la PSF réelle des miroirs segmentés, des branches de support ou d’une atmosphère turbulente."),
        F("u=πD sinθ/λ₀ ; I/I(0)=[2J₁(u)/u]²\nPremier zéro : u≈3,831706 ⇒ sinθ₁≈1,21967 λ₀/D\nÉtoiles indépendantes : Itotal(x)=I₁ PSF(x−s/2)+I₂ PSF(x+s/2)"),
        P("Rayleigh.", "Pour deux points de flux égaux et une pupille circulaire sans aberration, la séparation de Rayleigh place le maximum de l’un au premier zéro de l’autre. C’est un critère conventionnel de discernabilité, non une frontière absolue d’inférence à partir de données bruitées."),
        P("Obstruction.", "Une pupille annulaire de rapport ε donne A(u)∝2[J₁(u)−εJ₁(εu)]/[u(1−ε²)]. Le pic normalisé peut se resserrer tandis que les anneaux se renforcent et que le flux collecté baisse d’un facteur 1−ε². Utiliser le même repère 1,22λ/D ne prétend pas recalculer le zéro annulaire."),
        P("Exemple.", "D=200 mm, λ₀=550 nm donnent le repère de 0,692 seconde d’arc. Doubler D le divise par deux ; doubler seulement le grossissement de l’oculaire ne change pas la PSF angulaire. Un compagnon faible exige un contraste plus grand que deux étoiles égales.")),
    lesson("36. Optique non linéaire χ² : accord de phase et bilan photonique", "Au-delà accompagné", "nonlineaire",
        P("Processus.", "Une polarisation quadratique mélange les champs et peut générer une onde à 2ω. Le laboratoire traite le doublage dégénéré d’une seule pompe, avec d=χeff/2. Les indices nω et n2ω et le coefficient d en m·V⁻¹ normalisent l’efficacité. Le désaccord effectif Δk est réglé séparément : une orientation ou un quasi-accord peut le modifier tandis que ces indices de normalisation restent approchés comme fixes. Le banc ne recalcule donc pas automatiquement Δk=(4π/λ₀)(n2ω−nω)."),
        F("Pompe constante : η=I2ω/Iω, entrée≈[2ω²d²IωL²/(nω² n2ω ε₀c³)] sinc²(ΔkL/2)\nΔk=0 ⇒ η∝IωL² au faible taux ; longueur de cohérence Lc=π/|Δk|\nManley–Rowe dégénéré : Nω+2N2ω constant ; Iω+I2ω constant"),
        P("Dérivation.", "Une enveloppe harmonique engendrée vérifie E′2ω∝Eω² exp(iΔkz). Si Eω varie peu, son intégrale de 0 à L est L exp(iΔkL/2)sinc(ΔkL/2). Le carré donne le facteur de phase et la loi L². Un rendement calculé supérieur à 1 annonce l’échec de la pompe constante."),
        P("Déplétion.", "Les ondes couplées normalisées du laboratoire conservent |u|²+|v|²=1 ; à accord parfait, η=tanh²(κL). La pompe s’épuise progressivement et le rendement reste borné. Un désaccord peut donner une reconversion et des oscillations plutôt qu’une croissance monotone."),
        P("Lien au recueil.", "L’exemple du PDF à deux pompes distinctes de fréquence ω conserve N₁+N₃ et N₂+N₃ : chaque photon généré consomme un photon de chaque pompe. Une seule pompe dégénérée en consomme deux. Deux photons de 1064 nm donnent un photon de 532 nm ; l’énergie est conservée, le nombre total de photons ne l’est pas.")),
]

EXERCISES = [
    exercise("1. Deux sens de traversée", "Sup", "snell",
        "Un rayon traverse air→verre n=1,50 sous 45°. Déterminer l’angle réfracté, la longueur d’onde dans le verre pour λ₀=600 nm et le seuil de réflexion totale dans le trajet inverse. Expliquer quelle grandeur reste inchangée à l’interface.",
        "Snell donne sin r=sin45°/1,50, soit r≈28,13°. Dans le verre λ=600/1,50=400 nm tandis que ν=c/λ₀≈4,997×10¹⁴ Hz est inchangée : les conditions aux limites sont imposées à chaque instant. Pour verre→air, ic=arcsin(1/1,50)≈41,81°. Le trajet réciproque sous 28,13° sort sous 45° : il reste sous ce seuil. Mesurer les angles à la surface donnerait un résultat faux. La vitesse de phase et la longueur d’onde changent ensemble, sans modification de la fréquence."),
    exercise("2. Une interface transmet 96 %, pas 100 %", "Spé", "snell",
        "À incidence normale air→verre n=1,50, établir r et t du champ électrique à partir de la continuité de E et H. Calculer R, T. Déterminer ensuite l’incidence de Brewster pour la polarisation p.",
        "Les équations 1+r=t et n₁(1−r)=n₂t donnent r=(n₁−n₂)/(n₁+n₂)=−0,20 et t=2n₁/(n₁+n₂)=0,80. Donc R=0,040 et T=(n₂/n₁)t²=1,50×0,64=0,960 ; R+T=1. Le carré t² seul ne mesure pas une transmission de puissance : l’impédance diffère entre les milieux. Pour p, l’annulation de rp donne tan iB=n₂/n₁, d’où iB≈56,31°. Le faisceau s ne s’annule pas à cette incidence, ce qui permet d’obtenir une réflexion polarisée."),
    exercise("3. Une loupe produit-elle une image sur l’écran ?", "Sup", "lentille",
        "Une lentille de f′=80 mm observe un objet de hauteur 12 mm situé à 50 mm devant elle. Calculer position, nature et taille de l’image. Refaire le calcul pour l’objet à 200 mm.",
        "Les distances sont p=−50 mm et f′=+80 mm. p′=f′p/(p+f′)=−133,33 mm ; γ=p′/p=+2,6667, donc la hauteur est +32 mm. L’image est virtuelle et droite ; un écran placé au point apparent ne reçoit pas ces rayons convergents. À p=−200 mm, p′=133,33 mm, γ=−2/3 et A′B′=−8 mm : l’image est réelle, renversée et projetable. Les deux résultats ont le même |p′| par coïncidence des nombres ; leur signe décrit des situations optiques différentes."),
    exercise("4. Deux lentilles séparées : la somme des vergences échoue", "Sup → Spé", "lentille",
        "Deux lentilles minces ont f′₁=100 mm et f′₂=200 mm, séparées de 100 mm dans l’air. Calculer M=L₂T(d)L₁ et la vergence équivalente. Expliquer pourquoi la focale équivalente ne localise pas directement le foyer depuis L₂.",
        "En mètres, C₁=10 et C₂=5 δ. T a les coefficients A=D=1, B=0,10 m, C=0 ; le produit M=L₂TL₁ donne A=0, B=0,10 m, C=−10 m⁻¹, D=0,50. det M=0×0,50−0,10×(−10)=1. La vergence vaut −C=10 δ et f′équiv=100 mm. Pour une entrée parallèle uentrée=0, ysortie=A yentrée=0 : les rayons traversent l’axe au plan de L₂. Le foyer arrière est donc à ce plan, pas à 100 mm de L₂ ; cette dernière longueur se mesure depuis le plan principal image."),
    exercise("5. Mesure de Bessel et tailles réciproques", "Sup ; TP", "bessel",
        "On mesure D=800 mm et deux positions de lentille séparées de d=400 mm. Calculer f′, les deux distances depuis l’objet et leurs grandissements. Quel test supplémentaire utiliser avec une mire graduée ?",
        "f′=(D²−d²)/(4D)=(640000−160000)/3200=150 mm. Les positions sont (D−d)/2=200 mm et (D+d)/2=600 mm. À la première, l’image est à 600 mm de la lentille et γ=−600/200=−3 ; à la seconde γ=−200/600=−1/3. Les deux images sont renversées et γ₁γ₂=1. Mesurer les tailles d’un même intervalle de mire vérifie ce produit et la nature des deux réglages. Si D<4f′ aucune des deux positions réelles n’existe ; à D=4f′ elles se confondent à mi-distance."),
    exercise("6. Bessel : une incertitude calculée et une limite expérimentale", "Sup → Spé", "bessel",
        "Pour D=800 mm, d=400 mm, u(D)=u(d)=1 mm indépendants, calculer u(f′). Interpréter l’idée de se rapprocher de D=4f′ pour diminuer la sensibilité à d.",
        "f′=D/4−d²/(4D), donc fD=1/4+d²/(4D²)=0,3125 et fd=−d/(2D)=−0,25. L’incertitude standard est √[(0,3125)²+(0,25)²] mm≈0,400 mm. On rapporte (150,0±0,4) mm avec le statut standard de l’incertitude. Quand D→4f′, d→0 et fd→0, mais les deux mises au point deviennent indiscernables : u(d) n’a aucune raison de rester 1 mm. Un choix expérimental doit inclure la précision réelle de netteté, les corrélations de lecture et les limites du modèle mince."),
    exercise("7. Changer l’oculaire d’une lunette", "Sup", "telescope",
        "Une lunette afocale possède fo=1000 mm et D=100 mm. Comparer les oculaires de 25 et 10 mm : séparation, grossissement et pupille de sortie. Un détail de 1 minute d’arc devient apparent sous quel angle ?",
        "Avec fe=25 mm, d=1025 mm, G=−40 et la pupille de sortie vaut 100/40=2,50 mm. Avec fe=10 mm, d=1010 mm, G=−100 et la pupille vaut 1,00 mm. Le détail de 1 minute d’arc devient apparent sous 40 minutes puis 100 minutes d’arc, soit environ 0,667° et 1,667°, avec inversion. Il faut régler de nouveau l’écartement : conserver 1025 mm avec le second oculaire ne reste pas afocal. Le diamètre objectif inchangé garde la même limite de diffraction angulaire ; le fort grossissement peut simplement rendre un flou plus grand."),
    exercise("8. Un détecteur au foyer d’un télescope", "Sup → Spé", "telescope",
        "Pour D=200 mm, f=2000 mm, λ₀=550 nm, déterminer la séparation de Rayleigh angulaire et sa taille au foyer. Un pixel de 10 μm représente-t-il correctement cette séparation ? Que change un doublement de f à D fixé ?",
        "θR=1,22λ₀/D=3,355×10⁻⁶ rad≈0,692 seconde d’arc. Au foyer, s=fθR=6,71 μm. Un pixel de 10 μm est plus large que cette séparation : l’image est sous-échantillonnée à cette échelle, même si une modélisation de pixels peut parfois estimer une position. Avec f doublée, s=13,42 μm et le champ angulaire d’un pixel est divisé par deux ; θR reste inchangé car D ne change pas. L’angle de résolution, la taille physique de PSF et l’échantillonnage du détecteur répondent à trois paramètres distincts."),
    exercise("9. Régler un microscope afocal", "Sup ; TP", "microscope",
        "Un microscope a fo=8 mm, fe=25 mm et Δ=160 mm. Trouver la position de l’objet donnant une image intermédiaire au foyer de l’oculaire, le grandissement de l’objectif et le grossissement commercial avec d₀=250 mm.",
        "L’image intermédiaire est à p′=fo+Δ=168 mm de l’objectif. La conjugaison donne 1/p=1/168−1/8=−160/1344 mm⁻¹, soit p=−8,40 mm. Le grandissement exact du modèle mince vaut γ=p′/p=−20, égal ici à −Δ/fo. L’oculaire grossit par d₀/fe=10, donc G=−200. Un objet de 0,050 mm produit une image intermédiaire de −1,00 mm puis un angle d’environ 0,040 rad en valeur absolue. L’objet doit donc être légèrement au-delà du foyer, pas exactement au foyer, ce qui donnerait une image à l’infini avant l’oculaire."),
    exercise("10. Grossissement utile et résolution du microscope", "Spé", "microscope",
        "Comparer à λ₀=550 nm les résolutions de Rayleigh pour NA=0,10 et 0,25. Un objectif ×20 avec pixels de 6,5 μm côté caméra échantillonne-t-il suffisamment le second cas ? Quel serait l’effet d’un oculaire plus grossissant sur NA ?",
        "dR≈0,61λ₀/NA donne 3,355 μm pour NA=0,10 et 1,342 μm pour NA=0,25. Chaque pixel de la caméra représente 6,5/20=0,325 μm côté objet : le second détail couvre environ 4,13 pixels, une échelle raisonnablement échantillonnée dans ce modèle. L’oculaire ou un agrandissement supplémentaire change la taille apparente, pas la NA de l’objectif ni sa PSF ramenée à l’objet. Les valeurs supposent une pupille idéale et des points incohérents ; un objet périodique en illumination cohérente peut appeler un autre critère."),
    exercise("11. Accommodation à distance connue", "Sup", "oeil",
        "Dans l’œil réduit à ℓ=17 mm, calculer les vergences requises à l’infini, à 1 m et à 25 cm. Un excès de vergence de +3 δ est-il compensé par une lentille convergente ou divergente en contact ?",
        "La conjugaison à rétine fixe donne C=1/ℓ+1/s. À l’infini C=58,8235 δ ; à 1 m C=59,8235 δ ; à 25 cm C=62,8235 δ. L’accommodation ajoutée au repos normal est donc 0 δ, 1 δ et 4 δ respectivement. Un excès de +3 δ doit être compensé par −3 δ, une correction divergente en contact ; une convergence supplémentaire ferait avancer davantage le foyer. Le calcul utilise le modèle d’espace image en air et la correction collée ; une lentille distante de l’œil exige une composition de conjugaisons plutôt qu’une addition directe."),
    exercise("12. Pupille et défocalisation : fermer n’est pas toujours gagner", "Sup → Spé", "oeil",
        "Un faisceau convergerait 0,50 mm devant une rétine à ℓ=17 mm. Pour une pupille de 4 mm, estimer le diamètre du flou géométrique. Comparer le diamètre de tache d’Airy à 550 nm avec cette valeur ; que change une pupille divisée par deux ?",
        "Le foyer est à q=16,50 mm. Par triangles semblables, le diamètre géométrique à la rétine est b=D|ℓ−q|/q=4×0,50/16,50≈0,121 mm, soit 121 μm. L’Airy idéale a un diamètre entre premiers zéros 2,44λℓ/D≈5,70 μm : la défocalisation domine ici. Fermer à 2 mm divise le flou géométrique par deux mais double le diamètre diffractif à 11,4 μm. À forte fermeture et bonne mise au point, la diffraction finit donc par limiter le gain. Ces deux flous ne se somment pas universellement comme des diamètres ; leur comparaison donne des échelles."),
    exercise("13. Acceptance et seuil monomode", "Sup → Spé", "fibre",
        "Une fibre idéale a n₁=1,48, n₂=1,46 et un rayon de cœur a=4 μm. Calculer NA, l’angle d’entrée maximal dans l’air et V à 1550 nm. Quelle limite sur a donnerait V<2,405 ?",
        "NA=√(1,48²−1,46²)≈0,24249. L’angle d’entrée maximal est arcsin(NA)≈14,03°. V=2πaNA/λ₀≈3,932>2,405 : ce repère de fibre faiblement guidante ne garantit pas un régime monomode. Résoudre V<2,405 donne a<2,405λ₀/(2πNA)≈2,447 μm. La condition d’acceptance est géométrique ; le seuil 2,405 résulte de l’équation d’onde et de ses conditions aux limites cylindriques. Un rayon accepté dans une fibre très petite ne constitue pas à lui seul un calcul de mode."),
    exercise("14. Le guidage ne supprime pas la dispersion temporelle", "Sup → Spé", "fibre",
        "Dans une fibre uniforme de longueur 1 km et d’indice 1,48, comparer le temps d’un rayon axial à celui d’un rayon guidé à θ=8° avec l’axe. Donner un développement au second ordre en θ et expliquer le principe d’un gradient d’indice.",
        "Le temps axial vaut t₀=nL/c≈4,937 μs. Le rayon incliné parcourt L/cosθ, donc tθ=t₀/cos8° et Δt≈48,5 ns. Pour θ petit en radians, 1/cosθ=1+θ²/2+O(θ⁴), d’où Δt≈t₀θ²/2 ; avec θ≈0,1396, l’estimation donne environ 48,1 ns. La réflexion totale évite la fuite mais ne rend pas les longueurs égales. Un indice décroissant radialement fait parcourir les trajets éloignés dans un milieu plus rapide et peut compenser une partie de cet excès. Dispersion chromatique et pertes restent des mécanismes distincts."),
    exercise("15. Localiser le point bas d’un mirage", "Sup → Spé", "mirage",
        "Pour n(z)=n₀√(1+z/a), prendre a=20000 m, z₀=2 m et θ₀=−0,5°. À partir de z(x)=z₀+x tanθ₀+Ax², déterminer A, le point bas et le retour à l’altitude initiale. Le rayon rencontre-t-il le sol ?",
        "A=1/[4(a+z₀)cos²θ₀]≈1,2499702×10⁻⁵ m⁻¹. z′=tanθ₀+2Ax s’annule à x*=−tanθ₀/(2A)≈349,08 m. Le minimum est zmin=z₀−tan²θ₀/(4A)≈0,4768 m : il reste au-dessus du sol dans ce modèle. Le second passage à z=z₀ est x=−tanθ₀/A≈698,17 m. La valeur n₀ disparaît de la trajectoire car elle multiplie à la fois l’invariant et le profil ; elle reste dans le temps de parcours. Modifier a contrôle directement la courbure et peut changer l’interception du sol."),
    exercise("16. Vérifier une trajectoire sans intégrateur", "Spé", "mirage",
        "Dériver depuis l’invariant n(z)cosθ=n(z₀)cosθ₀ la courbure z″ et vérifier le coefficient de x². Déterminer une condition algébrique pour qu’un rayon initialement descendant touche z=0.",
        "Avec z′=tanθ, 1+z′²=1/cos²θ=(a+z)/[(a+z₀)cos²θ₀]. En dérivant hors du point bas puis en prolongeant continûment, z″=1/[2(a+z₀)cos²θ₀]. Une primitive avec z′(0)=tanθ₀ puis z(0)=z₀ donne A=1/[4(a+z₀)cos²θ₀], car (Ax²)″=2A. Le minimum vaut z₀−(a+z₀)sin²θ₀. Pour θ₀<0, une rencontre du sol est possible lorsque (a+z₀)sin²θ₀≥z₀, avec égalité pour une tangence. Une simulation physique du domaine z≥0 s’arrête à la première rencontre plutôt que continuer sous le sol."),
    exercise("17. Angle du premier arc-en-ciel", "Sup → Spé", "arcenciel",
        "Pour une goutte d’indice n=4/3, établir l’incidence stationnaire du trajet à une réflexion et calculer le rayon de l’arc primaire autour du point antisolaire. Expliquer le rôle de D′=0.",
        "D=π+2i−4r et sin i=n sin r donnent dr/di=cos i/(n cos r). D′=0 impose cos i/(n cos r)=1/2. En élevant au carré et utilisant sin²r=sin²i/n², 4(1−sin²i)=n²−sin²i, donc sin²i=(4−n²)/3. Pour n=4/3, i≈59,39°, r≈40,20° et Dmin≈137,970°. Le rayon antisolaire est 180°−Dmin≈42,030°. D′=0 concentre les incidences voisines dans une petite plage de directions, une caustique ; la diffraction et la source finie bornent la luminosité réellement observée."),
    exercise("18. Pourquoi le rouge est-il à l’extérieur ?", "Spé", "arcenciel",
        "Au rayon stationnaire primaire pour n=4/3, calculer ∂D/∂n. Estimer la variation du rayon antisolaire lorsque l’indice augmente de 0,006. Donner le sens du déplacement sans confondre déviation et rayon de l’arc.",
        "À i fixé, cos r ∂r/∂n=−sin r/n, donc ∂r/∂n=−tanr/n. D=π+2i−4r donne ∂D/∂n=4tanr/n≈2,53546 rad par unité d’indice au point stationnaire. Le déplacement d’i* ne contribue pas au premier ordre puisque ∂D/∂i=0. Pour Δn=0,006, ΔD≈0,01521 rad≈0,872°. Le rayon antisolaire β=π−D diminue donc d’environ 0,872°. Le violet possède l’indice plus grand et se place à l’intérieur du primaire ; le rouge à l’extérieur. L’ordre est inversé dans l’arc secondaire à deux réflexions."),
    exercise("19. Retrouver l’indice avec un goniomètre", "Sup ; TP", "prisme",
        "Un prisme d’angle A=60° donne Dmin=40°. Calculer n et l’incidence au minimum. Estimer la variation d’indice associée à une erreur de 0,10° sur Dmin, A étant supposé exact.",
        "Le trajet symétrique a r=r′=30° et i=i′=(A+Dmin)/2=50°. n=sin50°/sin30°≈1,532089. À A fixé, ∂n/∂Dmin=cos[(A+Dmin)/2]/[2sin(A/2)]≈0,642788 rad⁻¹. Une erreur de 0,10°=1,74533×10⁻³ rad donne Δn≈1,122×10⁻³. Utiliser directement 0,10 dans la dérivée en radians surestimerait l’erreur d’un facteur 180/π. Le minimum se repère par un retournement de la raie, puis les lectures de deux orientations peuvent limiter certaines erreurs d’alignement."),
    exercise("20. Cauchy : un ajustement avec unités", "Sup → Spé", "prisme",
        "On ajuste n(λ)=a+b/λ² avec λ en μm. Les mesures sont n(0,50)=1,496 et n(0,70)=1,4881633. Déterminer a, b puis n à 600 nm. Quel indice donnerait l’erreur consistant à insérer 600 sans conversion ?",
        "La différence vaut b(1/0,50²−1/0,70²). Elle donne b≈0,004000 μm² puis a=n(0,50)−4b≈1,480000. À 600 nm=0,600 μm, n=1,48+0,004/0,600²≈1,491111. Insérer 600 tout en gardant b en μm² donnerait 1,480000011, presque sans dispersion, une erreur d’unités. Le tracé de n en fonction de 1/λ² doit être linéaire dans la fenêtre de validité du modèle. Une extrapolation à une fréquence résonante ou à l’absorption ne se justifie pas par ces deux points."),
    exercise("21. Un miroir sphérique rapproche les rayons marginaux", "Sup → Spé", "aberrations",
        "Le miroir sphérique est x=−R+√(R²−y²), les rayons incidents vont vers +x. Montrer que l’intersection axiale du rayon de hauteur y est xf=−R+R/[2√(1−(y/R)²)]. Calculer xf pour y/R=0,05 et 0,45 avec R=400 mm.",
        "Au point P, une normale unitaire est n̂=(√(1−q²), q), q=y/R. La réflexion de (1,0) donne v=(−1+2q²,−2q√(1−q²)). En posant xaxe=xP−y vx/vy et en simplifiant, xf=−R+R/[2√(1−q²)]. Pour q=0,05, xf≈−199,750 mm ; pour q=0,45, xf≈−176,043 mm. Le foyer paraxial est −R/2=−200 mm ; les rayons marginaux focalisent plus près du sommet. Le signe et l’origine x=0 sont essentiels : une distance positive au miroir décrirait les mêmes positions avec un signe opposé."),
    exercise("22. Un paraboloïde axial est exactement stigmatique", "Spé", "aberrations",
        "Pour x=−y²/(2R), montrer qu’un front plan axial arrivant vers +x possède le même chemin géométrique jusqu’à F=(−R/2,0) pour chaque point P du miroir. En déduire le sens de la réflexion et discuter le hors axe.",
        "La distance PF vérifie PF²=(x+R/2)²+y². En substituant x=−y²/(2R), on obtient PF=R/2+y²/(2R)=R/2−x. Depuis un front plan x=x₀ avant le miroir, le trajet vaut (x−x₀)+PF=R/2−x₀, indépendant de y. La normale de la surface bisecte alors la direction incidente et PF conformément à la réflexion : tous les rayons axiaux passent en F. Cette propriété est exacte en géométrie, mais une pupille finie diffracte encore. Hors axe, l’égalité de chemins démontrée n’est plus valable ; la coma peut dégrader l’image."),
    exercise("23. Fermat : démontrer le minimum, pas seulement le trouver", "Sup → Spé", "fermat",
        "A et B sont à h₁=8 cm et h₂=5 cm de part et d’autre d’une interface ; leur séparation horizontale est X=20 cm. Pour des indices égaux, trouver le point de traversée et prouver son unicité. Que devient la position si seul n₂ augmente ?",
        "L(x)=n₁√(x²+h₁²)+n₂√[(X−x)²+h₂²]. Quand n₁=n₂, L′=0 donne x/h₁=(X−x)/h₂, donc x=Xh₁/(h₁+h₂)=160/13≈12,3077 cm : c’est l’intersection du segment AB. Pour tout n₁, n₂>0, L″=n₁h₁²/(x²+h₁²)³ᐟ²+n₂h₂²/[(X−x)²+h₂²]³ᐟ²>0, donc le minimum est unique. Augmenter n₂ rend L′ négatif au point précédent ; le nouveau zéro se déplace vers x plus grand, réduisant la longueur horizontale dans le milieu lent. La longueur euclidienne peut augmenter tandis que la durée diminue."),
    exercise("24. Principe variationnel et invariant du mirage", "Spé → Au-delà accompagné", "fermat",
        "Pour un indice n(z), écrire la fonctionnelle en paramètre x puis retrouver l’invariant horizontal par l’identité de Beltrami. Montrer comment on retrouve ncosθ et expliquer pourquoi Fermat parle en général de stationnarité.",
        "Le chemin optique est L[z]=∫n(z)√(1+z′²) dx. L’intégrande ℒ ne dépend pas explicitement de x ; l’identité de Beltrami donne ℒ−z′∂ℒ/∂z′=n(z)/√(1+z′²)=constante. Comme z′=tanθ, il s’agit de ncosθ. Cette intégrale première donne la trajectoire du mirage sans résoudre immédiatement une équation vectorielle. δL=0 ne suffit pas à prouver un minimum : il faut examiner la seconde variation ou la géométrie. La fonction à deux segments du laboratoire est strictement convexe, mais d’autres systèmes optiques possèdent plusieurs trajets stationnaires ou des points conjugués."),
]

EXERCISES += [
    exercise("25. Young : franges dans l’enveloppe", "Sup → Spé", "young",
        "Pour λ₀=600 nm, D=2 m, a=0,50 mm, b=0,040 mm, calculer l’interfrange, les premiers zéros de diffraction et le nombre de maxima d’interférence strictement dans le lobe central. Que donne un doublement de a ?",
        "i=λD/a=2,40 mm. Les zéros d’enveloppe sont à ±λD/b=±30,0 mm. Les maxima interférentiels sont x=ki avec k entier ; |k|<30/2,4=12,5 donne k=−12,…,12, donc 25 maxima dans le lobe central. Si a double, i devient 1,20 mm et |k|<25 ; on compte 49 maxima, les ordres ±25 tombant exactement sur les zéros et étant manquants. La largeur totale d’enveloppe reste 60 mm puisque b n’a pas changé. Un graphique doit donc faire voir deux échelles indépendantes, pas appeler interfrange la largeur de la tache diffractée."),
    exercise("26. Contraste, phase et sources indépendantes", "Sup → Spé", "young",
        "Les deux fentes ont I₂=0,10I₁. Calculer visibilité, maximum et minimum. Une phase additionnelle de π/2 déplace les maxima de combien d’interfranges ? Comparer avec deux sources indépendantes.",
        "V=2√0,10/1,10≈0,57496. Imax=(1+√0,10)²I₁≈1,73246I₁ et Imin=(1−√0,10)²I₁≈0,46754I₁. Avec φ(x)=2πx/i+φ₀, φ₀=π/2 impose xk=i(k−1/4), donc une translation de −i/4 selon cette convention. La visibilité reste la même. Deux sources indépendantes donnent ⟨cosφ⟩=0 : I=1,10I₁ multiplié par les enveloppes pertinentes, sans franges. La puissance moyenne ne disparaît pas quand la corrélation est supprimée. Une intensité déséquilibrée donne des minima non noirs même avec cohérence complète."),
    exercise("27. Résoudre le doublet du sodium avec un réseau", "Spé", "reseau",
        "Un réseau de pas d=2 μm observe les raies 589,0 et 589,6 nm à incidence normale. Estimer l’angle de l’ordre 1, la séparation angulaire et le nombre minimal de fentes éclairées selon Rayleigh. Refaire le seuil à l’ordre 2.",
        "À λm=589,3 nm, sinθ₁=λm/d=0,29465, donc θ₁≈17,137°. En différenciant d sinθ=mλ, Δθ≈mΔλ/(d cosθ)≈3,14×10⁻⁴ rad≈0,0180° à l’ordre 1. Le critère |m|N≥λm/Δλ donne N≥982,17, soit 983 fentes pour satisfaire strictement les valeurs arrondies ici. À l’ordre 2 il donne N≥491,08, soit 492 ; sinθ₂=0,5893 reste inférieur à 1. L’indication approximative 982 ou 491 décrit le voisinage du critère, mais une décision entière précise exige les longueurs d’onde et le seuil retenus."),
    exercise("28. Ordres manquants et pic du réseau", "Spé", "reseau",
        "Un réseau comporte N fentes de pas d et de largeur b=d/2. Montrer que les ordres pairs non nuls sont supprimés par l’enveloppe. Évaluer la somme d’amplitudes exactement au maximum malgré son quotient apparent 0/0.",
        "À l’ordre m, d sinθ=mλ et le facteur de fente vaut sinc(πb sinθ/λ)=sinc(πmb/d)=sinc(πm/2). Pour m=±2,±4,… il s’annule ; l’ordre zéro reste présent par prolongement sinc0=1. La somme ∑p=0…N−1exp(ipφ) vaut directement N à φ=2πm. Le quotient sin(Nφ/2)/sin(φ/2) a alors une limite de module N, donc l’intensité du facteur réseau vaut N². Mettre numérateur et dénominateur séparément à zéro créerait un pic absent artificiellement. Les ordres doivent encore satisfaire |sinθ|≤1 pour être propagatifs."),
    exercise("29. Rectangle : mesurer les deux dimensions d’une pupille", "Spé ; TP", "diffraction",
        "Une pupille uniforme produit au foyer f=300 mm sous λ=600 nm ses premiers zéros à X=±0,90 mm et Y=±0,225 mm. Retrouver a, b et les largeurs totales centrales. Justifier l’orientation de la figure.",
        "Les premiers zéros satisfont aX/(λf)=±1 et bY/(λf)=±1. Donc a=λf/0,90 mm=0,20 mm et b=λf/0,225 mm=0,80 mm. Les largeurs centrales sont 1,80 mm horizontalement et 0,450 mm verticalement. La pupille est quatre fois plus large verticalement, mais sa tache centrale est quatre fois plus étroite selon cette direction, conséquence du changement d’échelle de la transformée de Fourier. La position d’un premier zéro mesure une demi-largeur ; une largeur totale utilise les deux zéros symétriques, avec le facteur deux correspondant."),
    exercise("30. Apodisation : un faux zéro devient un point régulier", "Spé → Au-delà", "diffraction",
        "Pour t(x)=cos(πx/a) sur |x|≤a/2, établir A(u)/A(0), u=πa sinθ/λ. Trouver I/I(0) à u=π/2, les premiers zéros et la puissance transmise relative à une fente uniforme.",
        "Décomposer cos en deux exponentielles et intégrer donne A(u)=a(π/2)cosu/(π²/4−u²), donc A/A(0)=(π²/4)cosu/(π²/4−u²). À u→π/2, l’Hôpital donne cosu/(π²/4−u²)→1/π ; A/A(0)→π/4 et I/I(0)=π²/16≈0,61685, une valeur non nulle. Les premiers vrais zéros sont u=±3π/2, donc sinθ=±3λ/(2a). La puissance transmise vaut ∫−a/2ᵃ/²cos²(πx/a)dx=a/2 contre a pour t=1 : elle est divisée par deux. Des tracés normalisés au pic doivent être accompagnés de ce bilan."),
    exercise("31. Produire une polarisation circulaire", "Sup → Spé", "polarisation",
        "Avec exp(−iωt), l’entrée Jones normalisée est (cosθ, sinθ). Une lame d’axes x, y multiplie Ey par exp(iδ). Déterminer le résultat pour θ=45°, δ=90°, ses Stokes et la transmission par un analyseur quelconque.",
        "Le champ devient (1, i)/√2. Les composantes réelles sont cosωt/√2 et sinωt/√2 : le vecteur décrit un cercle dans le plan transverse. S₀=1, S₁=0, S₂=0, S₃=2Im(Ex*Ey)=1. L’analyseur d’angle β reçoit (cosβ+i sinβ)/√2 ; son module au carré vaut 1/2 pour tout β. À θ=0 ou 90°, une seule composante existe et la lame ne produit pas de cercle. Pour attribuer gauche/droite, il faut aussi déclarer le sens d’observation ; les valeurs complexes et Stokes donnent ici une convention sans ambiguïté."),
    exercise("32. Une demi-onde tourne la polarisation", "Spé", "polarisation",
        "Une entrée rectiligne fait 30° avec x. La lame demi-onde a son axe propre à 10° de x. Trouver l’orientation de sortie et la transmission d’un analyseur à 80°. Quel angle d’analyseur donne une extinction ?",
        "Dans la base de la lame, l’entrée est à θ−α=20°. La retardance π change le signe de la seconde composante, donc l’angle relatif devient −20°. Après retour aux axes du banc, θsortie=α−20°=−10°, égal à 2α−θ. L’analyseur à 80° est orthogonal à cet état puisque 80°−(−10°)=90°, donc sa transmission est cos²90°=0 dans le modèle idéal. Les angles de polarisation sont définis modulo 180° : une sortie à 170° est le même état rectiligne. La lame seule conserve la puissance ; c’est l’analyseur qui rejette le faisceau orthogonal."),
    exercise("33. Michelson : compter des franges et des anneaux", "Spé ; TP", "michelson",
        "Dans un Michelson à λ=546 nm, le miroir mobile avance de 100 μm. Combien de franges défilent en incidence normale ? Pour e=0,50 mm et f=200 mm, calculer l’écart de r² entre anneaux brillants consécutifs.",
        "Le miroir modifie un aller-retour : Δδ=2Δe=200 μm, donc N=Δδ/λ≈366,30 franges ; un comptage de 366 correspond à un déplacement voisin de 99,918 μm. Pour la lame d’air, δ≈2e−e r²/f². Deux anneaux brillants successifs diffèrent d’un ordre, donc |Δr²|=λf²/e=0,546 μm×(200 mm)²/(0,50 mm)=43,68 mm². Cette différence est constante, tandis que Δr ne l’est pas. Les anneaux se resserrent vers l’extérieur et le centre n’est pas automatiquement un maximum pour une épaisseur quelconque."),
    exercise("34. Coin d’air et identification du plan d’observation", "Spé ; TP", "michelson",
        "Un coin d’air a α=0,15 mrad sous λ=600 nm. Déterminer l’interfrange et son changement pour α doublé. Pourquoi observe-t-on cette figure dans un plan image plutôt que confondre x avec l’angle du montage en lame d’air ?",
        "δ(x)=δ₀+2αx ; une augmentation d’un ordre demande 2αi=λ, d’où i=λ/(2α)=600×10⁻⁹/(3×10⁻⁴)=2,00 mm. Pour α=0,30 mrad, i=1,00 mm. x repère une épaisseur locale du coin, tandis que les anneaux d’une lame plane sont des franges d’égale inclinaison et leur distance focale représente une direction. Le plan image du coin localise les variations d’épaisseur. Une mauvaise localisation d’observation peut dégrader les franges d’une source étendue ; déplacer la lentille sans reconsidérer cette distinction n’est pas un simple changement d’échelle."),
    exercise("35. Demi-visibilité d’un spectre gaussien", "Spé", "coherence",
        "Le spectre en fréquence est gaussien de largeur FWHM Δν=20 GHz. À quelle différence de marche la visibilité tombe-t-elle à 1/2 ? Donner V pour δ=2 mm et expliquer pourquoi une largeur de cohérence exige un seuil.",
        "V=exp[−π²Δν²(δ/c)²/(4ln2)]. Résoudre V=1/2 donne δ1/2=2ln2·c/(πΔν)≈6,615 mm. À δ=2 mm, l’exposant vaut environ −0,06336, donc V≈0,9386. Le raccourci c/Δν≈14,99 mm donne une échelle, pas cette demi-visibilité. Un seuil à 1/e, une largeur totale autour de δ=0 ou une intégrale de V² donneraient d’autres nombres. La visibilité est un module ; la phase rapide centrée sur la fréquence moyenne situe les franges mais ne change pas cette enveloppe gaussienne."),
    exercise("36. Doublet et source étendue : un diagnostic à deux réglages", "Spé", "coherence",
        "Un doublet autour de 589,3 nm a Δλ=0,60 nm. Estimer la première annulation de visibilité et l’écart des annulations en position e du miroir de Michelson. Pour Young à λ=600 nm, a=0,50 mm, Ds=1 m, quelle largeur uniforme s annule la cohérence spatiale ?",
        "Δν≈cΔλ/λ² et V=|cos(πΔνδ/c)| donnent la première annulation δ₀≈λ²/(2Δλ)≈0,28940 mm. Les annulations suivantes sont séparées de Δδ≈λ²/Δλ≈0,57879 mm. Avec δ=2e, e₀≈0,14470 mm et leur espacement Δe≈0,28940 mm. Pour la source uniforme, le premier zéro de sinc[πas/(λDs)] impose s=λDs/a=1,20 mm. Réduire s peut rétablir le contraste spatial mais ne supprime pas les annulations périodiques du doublet. Balayer e puis s sépare donc deux mécanismes qui produisent tous deux une baisse de visibilité."),
    exercise("37. Les deux nombres appelés F au Fabry–Perot", "Spé → Au-delà", "fabryperot",
        "Une cavité idéale a R=0,90 et e=5 mm dans l’air. Calculer coefficient d’Airy F, transmission minimale, FSR, finesse ℱ et largeur FWHM d’un pic. Ne pas assimiler F à ℱ.",
        "F=4R/(1−R)²=360 et Tmin=1/(1+F)=1/361≈0,002770. FSR=c/(2e)≈29,979 GHz. La demi-hauteur implique sin²(φ/2)=1/F, donc la largeur totale de phase est 4arcsin(1/√F). La finesse est ℱ=2π/[4arcsin(1/√F)]≈29,790 ; l’approximation π√R/(1−R)≈29,804 est proche. La largeur en fréquence vaut FSR/ℱ≈1,006 GHz. F=360 mesure le coefficient du sinus dans la transmission ; ℱ≈29,8 est un rapport d’intervalle spectral à largeur, deux objets distincts."),
    exercise("38. Résonance et angle d’une lame", "Spé → Au-delà", "fabryperot",
        "La cavité a n=1,50, e=1 mm et λ₀=600 nm à incidence normale. Calculer l’ordre. Pour un angle interne θ=2°, estimer le décalage de longueur d’onde du même ordre et expliquer l’effet d’un faisceau angulairement large.",
        "La résonance vérifie 2ne cosθ=mλ₀. À θ=0, m=2×1,50×1 mm/(600 nm)=5000. À ordre fixé, λ(θ)=λ(0)cosθ≈600×0,999390827=599,6345 nm ; le décalage est environ −0,3655 nm. L’expansion donne Δλ/λ≈−θ²/2 avec θ en radians. Un faisceau à plusieurs angles mélange des résonances déplacées, ce qui peut élargir le pic mesuré même si les miroirs gardent le même R. L’angle externe doit d’abord être converti par Snell ; substituer 2° externe à l’angle interne change ce décalage."),
    exercise("39. Où placer le masque de Fourier ?", "Spé", "fourier",
        "Un objet porte une modulation de période 50 μm. Le montage 4f utilise λ=600 nm et f=200 mm. À quelle distance du centre se trouvent ses deux fréquences ? Un disque passe-bas de rayon 1,5 mm les conserve-t-il ?",
        "La fréquence est ν=1/(50 μm)=20 mm⁻¹=20000 m⁻¹. Le plan de Fourier donne X=λfν=600×10⁻⁹×0,20×20000=2,40 mm ; les deux composantes d’une modulation cosinus sont à ±2,40 mm. Le masque de rayon 1,5 mm ne les transmet pas ; il conserve la composante moyenne au centre et réduit cette modulation. Sa coupure est νc=1,5 mm/(λf)=12,5 mm⁻¹. Ce calcul concerne une modulation d’amplitude du champ cohérent ; appliquer directement le masque au spectre d’une intensité photographique représenterait une autre expérience."),
    exercise("40. Parseval, masque passif et aliasing", "Spé → Au-delà", "fourier",
        "La grille a un pas de 10 μm et 256 points sur un axe. Calculer fréquence de Nyquist et espacement spectral. Un masque H de module ≤1 peut-il augmenter la puissance totale du champ ? Une modulation de 80 mm⁻¹ est-elle fidèle sur cette grille ?",
        "Δx=0,010 mm donne fNyquist=1/(2Δx)=50 mm⁻¹ et Δf=1/(NΔx)=1/2,56≈0,390625 mm⁻¹. Pour une FFT unitaire, Parseval donne ∑|Eimage|²=∑|H Ẽ|²≤∑|Ẽ|²=∑|Eobjet|². Un filtre passif peut augmenter localement une intensité par redistribution mais pas la norme totale. 80 mm⁻¹ dépasse Nyquist ; avec une fréquence d’échantillonnage de 100 mm⁻¹ elle se replie à −20 mm⁻¹, indistinguable sur ces échantillons. Augmenter la coupure d’un masque ne récupère pas l’information perdue avant le filtrage."),
    exercise("41. Une cavité stable qui ne lase pas", "Spé → Au-delà", "laser",
        "L=0,20 m, Rcourbure1=Rcourbure2=0,50 m, Rmiroir1=0,99, Rmiroir2=0,90 et α=0,05 m⁻¹. Tester la stabilité et calculer gseuil. Le gain g₀=0,10 m⁻¹ suffit-il ?",
        "g₁=g₂=1−0,20/0,50=0,60, donc leur produit 0,36 est à l’intérieur de 0<g₁g₂<1 : la cavité possède un confinement paraxial stable. Le seuil d’intensité est gseuil=α−ln(0,99×0,90)/(2L)=0,05−ln(0,891)/0,40≈0,338527 m⁻¹. g₀=0,10 est inférieur : le multiplicateur aller-retour R₁R₂exp[2(g₀−α)L] reste inférieur à 1. La présence d’un mode stable ne produit pas une amplification suffisante. Les R de courbure ont des unités de m et les réflectivités sont sans dimension, malgré une lettre souvent commune."),
    exercise("42. Saturation et puissance de sortie", "Spé → Au-delà", "laser",
        "Reprendre gseuil=0,338527 m⁻¹, avec g₀=1 m⁻¹ et Ps=2 W. Utiliser g(P)=g₀/(1+P/Ps) pour estimer P et la puissance transmise par le coupleur à R=0,90. Que devient le résultat sous le seuil ?",
        "Le régime établi impose g(P)=gseuil. P=Ps(g₀/gseuil−1)=2(1/0,338527−1)≈3,908 W. Le coupleur transmet ici environ (1−0,90)P≈0,3908 W. En dessous du seuil la solution algébrique serait négative, mais elle n’est pas une puissance physique : ce modèle d’oscillation prend P=0 sans traiter l’émission spontanée. La saturation est une réduction du gain disponible, non un mécanisme qui crée de l’énergie. Le résultat simplifié suppose un gain uniforme et un seul mode, sans dynamique de population ni distinction plus fine des puissances parcourant chaque direction."),
    exercise("43. Waist et intensité maximale", "Spé → Au-delà", "gaussien",
        "Un TEM₀₀ dans l’air a w₀=50 μm, λ₀=633 nm, P=2 mW. Calculer zR, la divergence, l’intensité axiale au waist et à zR. Quelles grandeurs restent constantes lorsque le faisceau s’élargit ?",
        "zR=πw₀²/λ₀≈12,4076 mm ; θdiv≈λ₀/(πw₀)≈4,030 mrad. Iaxe(0)=2P/(πw₀²)≈5,093×10⁵ W·m⁻². À z=zR, w=√2w₀ et Iaxe est divisée par deux, environ 2,546×10⁵ W·m⁻². La puissance totale reste P car 2π∫I(r, z)rdr=P à chaque z. La divergence concerne le rayon à 1/e² et non le diamètre complet ; un angle d’ouverture total donnerait environ 2θdiv. La courbure du front d’onde et la phase de Gouy évoluent également, sans perte d’énergie dans ce milieu idéal."),
    exercise("44. Quelle fraction de puissance traverse un diaphragme ?", "Spé", "gaussien",
        "Intégrer l’intensité gaussienne pour trouver la fraction de P dans un disque de rayon a. Calculer cette fraction pour a=w et a=2w. À z=zR, un diaphragme de rayon fixe w₀ transmet quelle fraction ?",
        "La puissance du disque est 2π∫₀ᵃ[2P/(πw²)]exp(−2r²/w²)rdr=P[1−exp(−2a²/w²)]. À a=w, la fraction vaut 1−e⁻²≈0,864665 ; à a=2w, 1−e⁻⁸≈0,999665. À z=zR, w=√2w₀ ; le diaphragme fixe a=w₀ transmet 1−e⁻¹≈0,632121. Le faisceau sans diaphragme conserve sa puissance, mais le flux transmis par une ouverture fixe diminue quand il s’élargit. Une troncature nette modifie aussi la diffraction en aval ; prolonger ensuite exactement le même TEM₀₀ serait une approximation supplémentaire."),
    exercise("45. Deux étoiles et une pupille circulaire", "Spé", "airy",
        "Deux étoiles de même flux sont séparées de 0,70 seconde d’arc. À λ=550 nm, quel diamètre circulaire idéal atteint le critère de Rayleigh ? Pourquoi doit-on sommer leurs intensités plutôt que leurs amplitudes ?",
        "θ=0,70/206264,806≈3,3937×10⁻⁶ rad. D≈1,22λ/θ≈0,19772 m, soit environ 198 mm. Les étoiles ont des phases mutuellement indépendantes à l’échelle de la mesure : la moyenne du produit croisé des champs est nulle. Le profil est donc la somme de deux PSF d’intensité centrées aux deux positions, pas le carré d’une somme d’amplitudes à phase fixée. Rayleigh suppose deux flux égaux et une pupille idéale ; une étoile dix fois plus faible peut être beaucoup plus difficile à détecter à la même séparation. Le grossissement d’un oculaire ne change pas le diamètre D."),
    exercise("46. Obstruction : un pic étroit ne suffit pas", "Spé → Au-delà", "airy",
        "Une pupille annulaire a le rapport ε=0,40 entre diamètre central opaque et diamètre extérieur. Calculer la fraction de flux collecté et établir la limite A(0) de A(u)=2[J₁(u)−εJ₁(εu)]/[u(1−ε²)]. Pourquoi ne conclut-on pas seulement à une meilleure résolution si le pic se resserre ?",
        "La surface transparente est πD²(1−ε²)/4, soit une fraction 1−0,16=0,84 de celle du disque plein. Comme J₁(u)=u/2+O(u³), le numérateur vaut u(1−ε²)+O(u³) et A(0)=1 avec cette normalisation au pic. La PSF redistribue davantage d’énergie dans les anneaux ; sa largeur centrale et son contraste de compagnon faible ne s’améliorent pas nécessairement ensemble. Le repère 1,22λ/D est celui du disque plein, pas le premier zéro recalculé de l’anneau. Une comparaison normalisée au maximum masque aussi les 16 % de lumière perdue."),
    exercise("47. Conversion χ² et première extinction de phase", "Au-delà accompagné", "nonlineaire",
        "Avec λω=1064 nm, d=5 pm·V⁻¹, nω=n2ω=1,65, Iω=0,20 GW·cm⁻², L=1 mm, estimer le rendement de pompe constante à accord parfait. Quel désaccord Δk donne sa première annulation ? La même formule reste-t-elle crédible à L=3 mm ?",
        "Convertir Iω=0,20×10¹³=2×10¹² W·m⁻² et ω=2πc/λω. η=2ω²d²IωL²/(nω²n2ωε₀c³)≈0,29245 à accord parfait. La première annulation de sinc²(ΔkL/2) est |Δk|L/2=π, donc |Δk|=2π/L≈6,283 mm⁻¹. À L=3 mm, la loi L² donnerait η≈2,632>1, impossible avec une seule pompe sans apport supplémentaire : la déplétion doit être incluse. Même 29 % n’est plus une conversion très faible ; le modèle couplé est préférable pour un résultat précis. Le coefficient d=χeff/2 dépend de la convention tensorielle annoncée."),
    exercise("48. Un bilan de photons qui n’est pas leur nombre total", "Au-delà accompagné", "nonlineaire",
        "Une pompe à 1064 nm fournit 10⁶ photons par intervalle et convertit 60 % de son énergie en seconde harmonique. Compter les photons résiduels et générés. Avec η=tanh²(κL), trouver κL pour η=1/2 ; comparer au modèle faible η≈(κL)².",
        "Un photon harmonique à 532 nm possède deux fois l’énergie d’un photon fondamental. La conversion de 60 % transforme donc 600000 photons fondamentaux en 300000 photons harmoniques ; il reste 400000 photons fondamentaux. Nω+2N2ω=400000+600000=10⁶ est conservé, tandis que Nω+N2ω=700000 ne l’est pas. η=1/2 donne κL=artanh(1/√2)≈0,881374 ; l’approximation faible donnerait alors η≈0,77686 et surestime la conversion. Dans l’exemple à deux pompes distinctes du recueil, chaque photon harmonique consomme un photon dans chaque branche : on conserve N₁+N₃ et N₂+N₃ séparément."),
]

